from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

# Required integer fields on every observation, all validated identically.
_OBS_FIELDS = ("x", "y", "value", "quality")

# Grid dimensional fields: (name, lower bound, upper bound or None, error message).
_GRID_SPECS = (
    ("width", 1, MAX_DIM, "bad width"),
    ("height", 1, MAX_DIM, "bad height"),
    ("cell_size", 1, None, "bad cell size"),
)


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if not {"grid", "observations", "fill_value"} <= set(raw):
        return {"ok": False, "error": "missing field"}
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if not {"width", "height", "cell_size"} <= set(grid):
        return {"ok": False, "error": "bad grid"}

    for name, lo, hi, message in _GRID_SPECS:
        value = grid[name]
        if not isinstance(value, int) or value < lo or (hi is not None and value > hi):
            return {"ok": False, "error": message}

    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    cell_size = grid["cell_size"]
    width = grid["width"]
    height = grid["height"]
    tolerance = cell_size // 2

    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0

    for obs in observations:
        if not isinstance(obs, dict):
            return {"ok": False, "error": "bad observation"}
        for field in _OBS_FIELDS:
            if field not in obs or not isinstance(obs[field], int):
                return {"ok": False, "error": "bad observation"}
        if not 0 <= obs["quality"] <= 100:
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        col = _axis_index(obs["x"], cell_size, width, tolerance)
        if col is None:
            dropped = dropped + 1
            continue
        row = _axis_index(obs["y"], cell_size, height, tolerance)
        if row is None:
            dropped = dropped + 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _axis_index(value: int, cell_size: int, limit: int, tolerance: int) -> int | None:
    """Map one axis coordinate to a grid index, or None if it falls outside."""
    if value < 0:
        return None
    index = value // cell_size
    if index < limit:
        return index
    if value - limit * cell_size >= tolerance:
        return None
    return limit - 1


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

