SATURATION_LIMIT = 5

_OBS_KEYS = ("x", "y", "value", "quality")
_DIM_LIMITS = (
    ("width", 1, MAX_DIM, "bad width"),
    ("height", 1, MAX_DIM, "bad height"),
    ("cell_size", 1, None, "bad cell size"),
)


def accumulate_grid(raw: object) -> dict:
    error = _validate_input(raw)
    if error:
        return {"ok": False, "error": error}
    grid = raw["grid"]
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    fill_value = raw["fill_value"]
    observations = raw["observations"]

    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        error = _validate_observation(obs)
        if error:
            return {"ok": False, "error": error}
        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue
        row = _to_index(obs["y"], height, cell_size, tolerance)
        col = _to_index(obs["x"], width, cell_size, tolerance)
        if row is None or col is None:
            dropped = dropped + 1
            continue
        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _validate_input(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return "malformed input"
    if not all(k in raw for k in ("grid", "observations", "fill_value")):
        return "missing field"
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return "bad grid"
    if not all(k in grid for k in ("width", "height", "cell_size")):
        return "bad grid"

    for key, lo, hi, error in _DIM_LIMITS:
        value = grid[key]
        if not isinstance(value, int) or value < lo or (hi is not None and value > hi):
            return error

    if not isinstance(raw["fill_value"], int):
        return "bad fill value"
    if not isinstance(raw["observations"], list):
        return "bad observations"
    return None


def _validate_observation(obs: object) -> str | None:
    if not isinstance(obs, dict):
        return "bad observation"
    for key in _OBS_KEYS:
        if key not in obs or not isinstance(obs[key], int):
            return "bad observation"
    if obs["quality"] < 0 or obs["quality"] > 100:
        return "bad observation"
    return None


def _to_index(value: int, dim: int, cell_size: int, tolerance: int) -> int | None:
    if value < 0:
        return None
    index = value // cell_size
    if index < dim:
        return index
    if value - dim * cell_size < tolerance:
        return dim - 1
    return None


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    return [
        [sums[(row, col)] // counts[(row, col)] if (row, col) in counts else fill_value
         for col in range(width)]
        for row in range(height)
    ]


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    return [
        ["empty" if (row, col) not in counts else "degraded" if (row, col) in degraded else "good"
         for col in range(width)]
        for row in range(height)
    ]


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

