    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    # Accumulate each observation into its cell.
    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if not isinstance(obs, dict) or not _valid_observation(obs):
            return {"ok": False, "error": "bad observation"}
        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        col = _cell_index(obs["x"], width, cell_size, tolerance)
        if col is None:
            dropped = dropped + 1
            continue
        row = _cell_index(obs["y"], height, cell_size, tolerance)
        if row is None:
            dropped = dropped + 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    cells = _tabulate(_average_at(sums, counts, raw["fill_value"]), width, height)
    flags = _tabulate(_flag_at(counts, degraded), width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _valid_observation(obs: dict) -> bool:
    for field in _OBS_FIELDS:
        if field not in obs or not isinstance(obs[field], int):
            return False
    return 0 <= obs["quality"] <= 100


def _cell_index(value: int, size: int, cell_size: int, tolerance: int) -> int | None:
    """Clamp a coordinate to a cell; return None when it must be dropped."""
    if value < 0:
        return None
    index = value // cell_size
    if index >= size:
        if value - size * cell_size >= tolerance:
            return None
        index = size - 1
    return index


def _tabulate(fill_cell, width: int, height: int) -> list:
    """Build a height x width grid by asking fill_cell for each cell."""
    return [[fill_cell(row, col) for col in range(width)] for row in range(height)]


def _average_at(sums: dict, counts: dict, fill_value: int):
    def at(row: int, col: int) -> int:
        key = (row, col)
        if key in counts:
            return sums[key] // counts[key]
        return fill_value

    return at


def _flag_at(counts: dict, degraded: dict):
    def at(row: int, col: int) -> str:
        key = (row, col)
        if key not in counts:
            return "empty"
        if key in degraded:
            return "degraded"
        return "good"

    return at


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
