MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

# Per-top-level-field predicates, keyed in the order they are validated so a
# field's own error name stays accurate.
GRID_FIELDS = {
    "width": (lambda v: isinstance(v, int) and 1 <= v <= MAX_DIM, "width"),
    "height": (lambda v: isinstance(v, int) and 1 <= v <= MAX_DIM, "height"),
    "cell_size": (lambda v: isinstance(v, int) and 1 <= v, "cell size"),
}
OBS_FIELDS = ("x", "y", "value", "quality")


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if any(field not in raw for field in ("grid", "observations", "fill_value")):
        return {"ok": False, "error": "missing field"}

    grid = raw["grid"]
    if not isinstance(grid, dict) or any(field not in grid for field in GRID_FIELDS):
        return {"ok": False, "error": "bad grid"}
    for field, (check, name) in GRID_FIELDS.items():
        if not check(grid[field]):
            return {"ok": False, "error": "bad " + name}

    cell_size = grid["cell_size"]
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if not isinstance(obs, dict) or any(
            field not in obs or not isinstance(obs[field], int) for field in OBS_FIELDS
        ):
            return {"ok": False, "error": "bad observation"}
        if not 0 <= obs["quality"] <= 100:
            return {"ok": False, "error": "bad observation"}
        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        col, col_ok = _snap_coord(obs["x"], cell_size, grid["width"], tolerance)
        if not col_ok:
            dropped = dropped + 1
            continue
        row, row_ok = _snap_coord(obs["y"], cell_size, grid["height"], tolerance)
        if not row_ok:
            dropped = dropped + 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    cells, flags = _build_grid(sums, counts, degraded, grid["width"], grid["height"], raw["fill_value"])
    total = grid["width"] * grid["height"]
    coverage = len(counts) * 100 // total
    line = ";".join(
        "{key}={value}".format(key=key, value=value)
        for key, value in (
            ("cells", total),
            ("filled", len(counts)),
            ("dropped", dropped),
            ("rejected", rejected),
            ("saturated", saturated),
            ("coverage", coverage),
        )
    )
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _snap_coord(value: int, cell_size: int, dim: int, tolerance: int) -> tuple:
    """Map a value to a cell index, clamping values just past the last cell."""
    if value < 0:
        return 0, False
    index = value // cell_size
    if index >= dim:
        if value - dim * cell_size < tolerance:
            return dim - 1, True
        return 0, False
    return index, True


def _build_grid(sums: dict, counts: dict, degraded: dict, width: int, height: int, fill_value: int) -> tuple:
    """Materialize per-cell values and status flags from the accumulators."""
    cells = []
    flags = []
    for row in range(height):
        row_cells = []
        row_flags = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                row_cells.append(sums[key] // counts[key])
                row_flags.append("degraded" if key in degraded else "good")
            else:
                row_cells.append(fill_value)
                row_flags.append("empty")
        cells.append(row_cells)
        flags.append(row_flags)
    return cells, flags

