        if "quality" not in obs or not isinstance(obs["quality"], int):
            return {"ok": False, "error": "bad observation"}
        if obs["quality"] < 0 or obs["quality"] > 100:
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        key = _cell_for(obs["x"], obs["y"], width, height, cell_size, tolerance)
        if key is None:
            dropped = dropped + 1
            continue

        degraded_obs = obs["quality"] < GOOD_QUALITY
        entry = acc.get(key)
        if entry is None:
            acc[key] = (obs["value"], 1, degraded_obs)
        elif entry[1] >= SATURATION_LIMIT:
            saturated = saturated + 1
        else:
            value_sum, count, is_degraded = entry
            acc[key] = (value_sum + obs["value"], count + 1, is_degraded or degraded_obs)

    sums = {key: entry[0] for key, entry in acc.items()}
    counts = {key: entry[1] for key, entry in acc.items()}
    degraded = {key for key, entry in acc.items() if entry[2]}

    cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
