def _cell_for(x: int, y: int, width: int, height: int, cell_size: int, tolerance: int) -> tuple | None:
    """Map an observation (x, y) to its grid cell (row, col).

    Returns None if the point falls outside the grid, including beyond the snap
    tolerance at the far edge. The tolerance lets edge observations clamp to the
    last cell instead of being dropped.
