    if x < 0:
        return None
    col = x // cell_size
    if col >= width:
        if x - width * cell_size >= tolerance:
            return None
        col = width - 1

    if y < 0:
        return None
    row = y // cell_size
    if row >= height:
        if y - height * cell_size >= tolerance:
            return None
        row = height - 1

    return (row, col)


