GOOD_QUALITY = 60
SATURATION_LIMIT = 5

# (field, error message, max allowed size); max None means unlimited.
_GRID_FIELDS = (
    ("width", "bad width", MAX_DIM),
    ("height", "bad height", MAX_DIM),
    ("cell_size", "bad cell size", None),
)


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if not all(f in grid for f in ("width", "height", "cell_size")):
        return {"ok": False, "error": "bad grid"}
    for field, error, limit in _GRID_FIELDS:
        value = grid[field]
        if not isinstance(value, int) or value < 1 or (limit is not None and value > limit):
            return {"ok": False, "error": error}
    width, height, cell_size = grid["width"], grid["height"], grid["cell_size"]

    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if not isinstance(obs, dict):
            return {"ok": False, "error": "bad observation"}
        for field in ("x", "y", "value", "quality"):
            if field not in obs or not isinstance(obs[field], int):
                return {"ok": False, "error": "bad observation"}
        if not 0 <= obs["quality"] <= 100:
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        col = _axis_index(obs["x"], width, cell_size, tolerance)
        if col is None:
            dropped = dropped + 1
            continue
        row = _axis_index(obs["y"], height, cell_size, tolerance)
        if row is None:
            dropped = dropped + 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    cells, flags = _build_grid(sums, counts, degraded, width, height, raw["fill_value"])
    coverage = len(counts) * 100 // (width * height)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage),
    }


def _axis_index(value: int, size: int, cell_size: int, tolerance: int) -> int | None:
    if value < 0:
        return None
    index = value // cell_size
    if index < size:
        return index
    if value - size * cell_size < tolerance:
        return size - 1
    return None


def _build_grid(sums: dict, counts: dict, degraded: dict, width: int, height: int, fill_value: int):
    cells = []
    flags = []
    for row in range(height):
        cell_row = []
        flag_row = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cell_row.append(sums[key] // counts[key])
                flag_row.append("degraded" if key in degraded else "good")
            else:
                cell_row.append(fill_value)
                flag_row.append("empty")
        cells.append(cell_row)
        flags.append(flag_row)
    return cells, flags


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

from __future__ import annotations

from typing import Any

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

# Field names expected on every observation.
_OBS_FIELDS = ("x", "y", "value", "quality")


def accumulate_grid(raw: object) -> dict:
    """Fold raw point observations into an aggregated cell grid.

    Public API (signature and returned shape) is intentionally stable:
    callers rely on the exact result dict and its reported statistics.
    """
    parsed = _parse_input(raw)
    if parsed is None:
        return {"ok": False, "error": "malformed input"}
    if isinstance(parsed, str):
        return {"ok": False, "error": parsed}
    width, height, cell_size, fill_value, observations = parsed

    sums: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    degraded: set[tuple[int, int]] = set()
    dropped = rejected = saturated = 0

    tolerance = cell_size // 2
    for obs in observations:
        parsed_obs = _parse_observation(obs)
        if isinstance(parsed_obs, str):
            return {"ok": False, "error": parsed_obs}
        x, y, value, quality = parsed_obs

        if quality < MIN_QUALITY:
            rejected += 1
            continue

        col = _bin_coord(x, cell_size, width, tolerance)
        if col is None:
            dropped += 1
            continue
        row = _bin_coord(y, cell_size, height, tolerance)
        if row is None:
            dropped += 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + value
        counts[key] = counts.get(key, 0) + 1
        if quality < GOOD_QUALITY:
            degraded.add(key)

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _parse_input(raw: object) -> tuple[Any, ...] | str | None:
    """Validate the top-level payload.

    Returns a ``(width, height, cell_size, fill_value, observations)`` tuple on
    success, an error-message string for a specific validation failure, or
    ``None`` when ``raw`` is not a dict (no specific message applies).
    """
    if not isinstance(raw, dict):
        return None
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return "missing field"
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return "bad grid"
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return "bad grid"

    width, height, cell_size = grid["width"], grid["height"], grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return "bad width"
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return "bad height"
    if not isinstance(cell_size, int) or cell_size < 1:
        return "bad cell size"
    if not isinstance(raw["fill_value"], int):
        return "bad fill value"
    observations = raw["observations"]
    if not isinstance(observations, list):
        return "bad observations"

    return width, height, cell_size, raw["fill_value"], observations


def _parse_observation(obs: object) -> tuple[int, int, int, int] | str:
    """Validate one observation.

    Returns its ``(x, y, value, quality)`` fields on success, or an error
    string when the record is malformed.
    """
    if not isinstance(obs, dict):
        return "bad observation"
    if any(field not in obs for field in _OBS_FIELDS):
        return "bad observation"
    x, y, value, quality = obs["x"], obs["y"], obs["value"], obs["quality"]
    if not (
        isinstance(x, int)
        and isinstance(y, int)
        and isinstance(value, int)
        and isinstance(quality, int)
        and 0 <= quality <= 100
    ):
        return "bad observation"
    return x, y, value, quality


def _bin_coord(coord: int, cell_size: int, dim: int, tolerance: int) -> int | None:
    """Map a raw coordinate to a cell index, applying the edge clamp.

    Returns the cell index, or ``None`` when the coordinate falls outside the
    grid and cannot be clamped within tolerance.
    """
    if coord < 0:
        return None
    cell = coord // cell_size
    if cell < dim:
        return cell
    # The coordinate lands in the slack between the last cell's nominal edge
    # and the hard boundary; clamp it into the final cell when close enough.
    if coord - dim * cell_size < tolerance:
        return dim - 1
    return None


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            cells.append(sums[key] // counts[key] if key in counts else fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: set, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

from __future__ import annotations

"""Accumulate scattered observations into a regular grid.

Input is a ``dict`` describing a grid plus a list of observations.  Each
observation carries an ``(x, y)`` position, a ``value`` and a ``quality``.
Observations are binned into cells of the grid and averaged.  The public entry
point :func:`accumulate_grid` validates its input and never raises; it returns a
``dict`` with a boolean ``ok`` field, or a structured response describing the
full accumulated grid.

The public function signature and return contract are stable: callers may rely
on the exact keys and error strings described below.
"""

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    """Validate ``raw`` and accumulate ``observations`` into grid cells.

    Returns either ``{"ok": False, "error": <reason>}`` for malformed input, or
    on success a dict with keys ``ok``, ``cells``, ``flags``, ``dropped``,
    ``rejected``, ``saturated``, ``coverage`` and ``line``.
    """
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}

    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    sums: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    degraded: set[tuple[int, int]] = set()
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        if not _is_valid_observation(obs):
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        col = _bounded_index(obs["x"], cell_size, width, tolerance, width * cell_size)
        if col is None:
            dropped = dropped + 1
            continue

        row = _bounded_index(obs["y"], cell_size, height, tolerance, height * cell_size)
        if row is None:
            dropped = dropped + 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded.add(key)

    cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _is_valid_observation(obs: object) -> bool:
    """Return ``True`` when ``obs`` is a well-formed observation dict."""
    if not isinstance(obs, dict):
        return False
    if not isinstance(obs.get("x"), int):
        return False
    if not isinstance(obs.get("y"), int):
        return False
    if not isinstance(obs.get("value"), int):
        return False
    if not isinstance(obs.get("quality"), int):
        return False
    if obs["quality"] < 0 or obs["quality"] > 100:
        return False
    return True


def _bounded_index(coord: int, cell_size: int, dimension: int, tolerance: int, limit: int) -> int | None:
    """Map ``coord`` to a cell index, or return ``None`` when it must be dropped.

    Coordinates in the trailing margin ``[limit, limit + tolerance)`` clamp to
    the final cell; everything beyond that, plus any negative coordinate, is
    considered out of range and dropped (returned as ``None``).
    """
    if coord < 0:
        return None
    index = coord // cell_size
    if index >= dimension:
        if coord - limit < tolerance:
            return dimension - 1
        return None
    return index


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    """Build the ``height`` x ``width`` grid of averaged cell values."""
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: set, width: int, height: int) -> list:
    """Build a per-cell flag grid: ``empty``, ``degraded`` or ``good``."""
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    """Percentage of cells that received at least one observation."""
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    """Compose the human-readable one-line accumulator summary."""
    return (
        f"cells={total_cells};filled={filled};dropped={dropped};"
        f"rejected={rejected};saturated={saturated};coverage={coverage}"
    )

from __future__ import annotations

from typing import Any, Dict, Optional, Tuple

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    """Aggregate a set of observations into a 2D grid of averaged cells.

    The public signature and returned shape are fixed: a dict with keys
    ``ok``, ``cells``, ``flags`` and, on success, ``dropped``, ``rejected``,
    ``saturated``, ``coverage`` and ``line``.
    """
    params = _parse(raw)
    if isinstance(params, str):
        return {"ok": False, "error": params}

    grid, observations, fill_value = params
    width, height, cell_size = grid
    tolerance = cell_size // 2

    sums: Dict[int, int] = {}
    counts: Dict[int, int] = {}
    degraded: Dict[int, bool] = {}
    dropped = rejected = saturated = 0

    for obs in observations:
        error = _check_observation(obs)
        if error is not None:
            return {"ok": False, "error": error}

        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue

        index = _target_cell(obs, width, height, cell_size, tolerance)
        if index is None:
            dropped += 1
            continue

        if counts.get(index, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue

        sums[index] = sums.get(index, 0) + obs["value"]
        counts[index] = counts.get(index, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[index] = True

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)

    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _parse(raw: object) -> Any:
    """Validate and normalise the top-level input, returning either an error
    message (as a ``str``) or a tuple ``(grid, observations, fill_value)``."""
    if not isinstance(raw, dict):
        return "malformed input"
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return "missing field"

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return "bad grid"
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return "bad grid"

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return "bad width"
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return "bad height"
    if not isinstance(cell_size, int) or cell_size < 1:
        return "bad cell size"
    if not isinstance(raw["fill_value"], int):
        return "bad fill value"

    observations = raw["observations"]
    if not isinstance(observations, list):
        return "bad observations"

    return (width, height, cell_size), observations, raw["fill_value"]


def _check_observation(obs: object) -> Optional[str]:
    """Return an error message if an observation is malformed, else None."""
    if not isinstance(obs, dict):
        return "bad observation"
    if "x" not in obs or not isinstance(obs["x"], int):
        return "bad observation"
    if "y" not in obs or not isinstance(obs["y"], int):
        return "bad observation"
    if "value" not in obs or not isinstance(obs["value"], int):
        return "bad observation"
    if "quality" not in obs or not isinstance(obs["quality"], int):
        return "bad observation"
    if obs["quality"] < 0 or obs["quality"] > 100:
        return "bad observation"
    return None


def _target_cell(obs: dict, width: int, height: int, cell_size: int,
                 tolerance: int) -> Optional[int]:
    """Map an observation to a flat cell index, returning None if it falls
    outside the grid's acceptable bounds (i.e. should be dropped)."""
    x = obs["x"]
    if x < 0:
        return None
    col = x // cell_size
    if col >= width:
        if x - width * cell_size >= tolerance:
            return None
        col = width - 1

    y = obs["y"]
    if y < 0:
        return None
    row = y // cell_size
    if row >= height:
        if y - height * cell_size >= tolerance:
            return None
        row = height - 1

    return row * width + col


def _averaged_rows(sums: dict, counts: dict, width: int, height: int,
                   fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = [
            sums[row * width + col] // counts[row * width + col]
            if row * width + col in counts
            else fill_value
            for col in range(width)
        ]
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            index = row * width + col
            if index not in counts:
                flags.append("empty")
            elif index in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int,
                  saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

# Field names used throughout, centralised to avoid typos.
_GRID = "grid"
_OBSERVATIONS = "observations"
_FILL_VALUE = "fill_value"


def accumulate_grid(raw: object) -> dict:
    """Aggregate observations onto a grid.

    Public behaviour is preserved: returns either an error dict or a success
    dict with averaged cells, per-cell flags and aggregate statistics.
    """
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if _GRID not in raw or _OBSERVATIONS not in raw or _FILL_VALUE not in raw:
        return {"ok": False, "error": "missing field"}

    grid = raw[_GRID]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw[_FILL_VALUE], int):
        return {"ok": False, "error": "bad fill value"}

    observations = raw[_OBSERVATIONS]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    state = _GridAccumulator(cell_size, width, height)

    for obs in observations:
        error = _validate_observation(obs)
        if error is not None:
            return {"ok": False, "error": error}

        if obs["quality"] < MIN_QUALITY:
            state.rejected += 1
            continue
        state.place(obs)

    cells = _averaged_rows(state.sums, state.counts, width, height, raw[_FILL_VALUE])
    flags = _flag_rows(state.counts, state.degraded, width, height)
    coverage = _coverage(state.counts, width, height)
    line = _summary_line(
        width * height,
        len(state.counts),
        state.dropped,
        state.rejected,
        state.saturated,
        coverage,
    )
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": state.dropped,
        "rejected": state.rejected,
        "saturated": state.saturated,
        "coverage": coverage,
        "line": line,
    }


class _GridAccumulator:
    """Mutable per-call state for the observation aggregation loop."""

    __slots__ = ("cell_size", "width", "height", "tolerance",
                 "sums", "counts", "degraded", "dropped", "rejected", "saturated")

    def __init__(self, cell_size: int, width: int, height: int) -> None:
        self.cell_size = cell_size
        self.width = width
        self.height = height
        self.tolerance = cell_size // 2
        self.sums: dict = {}
        self.counts: dict = {}
        self.degraded: dict = {}
        self.dropped = 0
        self.rejected = 0
        self.saturated = 0

    def place(self, obs: dict) -> None:
        """Drop or accumulate a single (already quality-filtered) observation."""
        x = obs["x"]
        if x < 0:
            self.dropped += 1
            return
        col = x // self.cell_size
        if col >= self.width:
            if x - self.width * self.cell_size < self.tolerance:
                col = self.width - 1
            else:
                self.dropped += 1
                return

        y = obs["y"]
        if y < 0:
            self.dropped += 1
            return
        row = y // self.cell_size
        if row >= self.height:
            if y - self.height * self.cell_size < self.tolerance:
                row = self.height - 1
            else:
                self.dropped += 1
                return

        key = (row, col)
        if self.counts.get(key, 0) >= SATURATION_LIMIT:
            self.saturated += 1
            return
        self.sums[key] = self.sums.get(key, 0) + obs["value"]
        self.counts[key] = self.counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            self.degraded[key] = True


def _validate_observation(obs: object) -> str | None:
    """Return an error message if the observation is malformed, else ``None``.

    The checks mirror the original validation order exactly.
    """
    if not isinstance(obs, dict):
        return "bad observation"
    if "x" not in obs or not isinstance(obs["x"], int):
        return "bad observation"
    if "y" not in obs or not isinstance(obs["y"], int):
        return "bad observation"
    if "value" not in obs or not isinstance(obs["value"], int):
        return "bad observation"
    if "quality" not in obs or not isinstance(obs["quality"], int):
        return "bad observation"
    if obs["quality"] < 0 or obs["quality"] > 100:
        return "bad observation"
    return None


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    """Accumulate grid observations into per-cell averages with quality flags.

    Merges raw observations into a grid: each observation lands in a cell based
    on its (x, y) coordinates, values are averaged, and cells carry quality
    flags. Returns a result dict; on invalid input returns {"ok": False, ...}.
    """
    if not isinstance(raw, dict):
        return _fail("malformed input")
    try:
        grid = raw["grid"]
        observations = raw["observations"]
        fill_value = raw["fill_value"]
    except KeyError:
        return _fail("missing field")
    if not isinstance(grid, dict):
        return _fail("bad grid")

    spec = _grid_spec(grid)
    if not isinstance(spec, tuple):
        return _fail(spec)
    width, height, cell_size = spec
    if not isinstance(fill_value, int):
        return _fail("bad fill value")
    if not isinstance(observations, list):
        return _fail("bad observations")

    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if _reject_observation(obs):
            return _fail("bad observation")
        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        col, ok = _grid_coord(obs["x"], width, cell_size, tolerance)
        if ok is False:
            dropped = dropped + 1
            continue
        row, ok = _grid_coord(obs["y"], height, cell_size, tolerance)
        if ok is False:
            dropped = dropped + 1
            continue

        if _accumulate(sums, counts, degraded, row, col, obs):
            saturated = saturated + 1

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _fail(error: str) -> dict:
    return {"ok": False, "error": error}


def _grid_spec(grid: dict):
    """Validate a grid spec; return (width, height, cell_size) or an error string."""
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return "bad grid"
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or not 1 <= width <= MAX_DIM:
        return "bad width"
    if not isinstance(height, int) or not 1 <= height <= MAX_DIM:
        return "bad height"
    if not isinstance(cell_size, int) or cell_size < 1:
        return "bad cell size"
    return (width, height, cell_size)


def _reject_observation(obs) -> bool:
    """Return True if the observation is malformed and should abort the run."""
    if not isinstance(obs, dict):
        return True
    for field in ("x", "y", "value", "quality"):
        if field not in obs or not isinstance(obs[field], int):
            return True
    return not 0 <= obs["quality"] <= 100


def _grid_coord(coord: int, limit: int, cell_size: int, tolerance: int):
    """Map a coordinate to a cell index, or signal that it should be dropped."""
    if coord < 0:
        return None, False
    index = coord // cell_size
    if index >= limit:
        if coord - limit * cell_size < tolerance:
            index = limit - 1
        else:
            return None, False
    return index, True


def _accumulate(sums, counts, degraded, row, col, obs) -> bool:
    """Add an observation to a cell; return True if it was skipped as saturated."""
    key = (row, col)
    if counts.get(key, 0) >= SATURATION_LIMIT:
        return True
    sums[key] = sums.get(key, 0) + obs["value"]
    counts[key] = counts.get(key, 0) + 1
    if obs["quality"] < GOOD_QUALITY:
        degraded[key] = True
    return False


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    def average(key):
        return sums[key] // counts[key] if key in counts else fill_value

    return [[average((row, col)) for col in range(width)] for row in range(height)]


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    def flag(key):
        if key not in counts:
            return "empty"
        return "degraded" if key in degraded else "good"

    return [[flag((row, col)) for col in range(width)] for row in range(height)]


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    parts = (
        ("cells", total_cells),
        ("filled", filled),
        ("dropped", dropped),
        ("rejected", rejected),
        ("saturated", saturated),
        ("coverage", coverage),
    )
    return ";".join(f"{name}={value}" for name, value in parts)

