def _active(tier: str, member: dict):
    """Active members renew at the base tier fee."""
    return None, TIER_FEES[tier], "renewed"


def _lapsed(tier: str, member: dict):
    """Lapsed members pay a surcharge that grows the longer they were out."""
    days = member.get("expired_days")
    if not isinstance(days, int) or days < 0:
        return "bad expiry", None, None
    if days <= GRACE_DAYS:
        return None, TIER_FEES[tier] + LATE_FEE, "renewed"
    return None, TIER_FEES[tier] + REINSTATE_SURCHARGE, "reinstated"


def _suspended(tier: str, member: dict):
    """Suspended members must be under the strike limit to reactivate."""
    strikes = member.get("strikes")
    if not isinstance(strikes, int) or strikes < 0:
        return "bad strikes", None, None
    if strikes >= MAX_STRIKES:
        return "too many strikes", None, None
    return None, TIER_FEES[tier] + TIER_FEES[tier] // 2, "reactivated"


_PLANS = {"active": _active, "lapsed": _lapsed, "suspended": _suspended}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    member = raw_member
    payment = raw_payment
    if "id" not in member or "status" not in member or "tier" not in member:
        return {"ok": False, "error": "missing member field"}
    if "amount" not in payment or "method" not in payment:
        return {"ok": False, "error": "missing payment field"}
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return {"ok": False, "error": "bad member id"}

    status = member["status"]
    if status == "banned":
        return {"ok": False, "error": "member banned"}

    plan = _PLANS.get(status)
    if plan is None:
        return {"ok": False, "error": "unknown status"}

    tier = member["tier"]
    if tier not in TIER_FEES:
        return {"ok": False, "error": "unknown tier"}

    error, fee, new_status = plan(tier, member)
    if error:
        return {"ok": False, "error": error}

    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return {"ok": False, "error": "bad amount"}
    if payment["method"] not in SUPPORTED_METHODS:
        return {"ok": False, "error": "unsupported method"}
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}

    receipt = f"{payment['method']}:{member['id']}:{new_status}:{fee}"
    return {"ok": True, "status": new_status, "fee": fee, "receipt": receipt}

