# Each status plan is a genuinely separate job: given the member and the
# tier's base fee it derives the outcome label and the fee surcharge, or
# returns (None, error) when that status's own data is invalid.
def _plan_active(_member, _base_fee):
    return "renewed", 0


def _plan_lapsed(member, _base_fee):
    days = member.get("expired_days")
    if not isinstance(days, int) or days < 0:
        return None, "bad expiry"
    if days <= GRACE_DAYS:
        return "renewed", LATE_FEE
    return "reinstated", REINSTATE_SURCHARGE


def _plan_suspended(member, base_fee):
    strikes = member.get("strikes")
    if not isinstance(strikes, int) or strikes < 0:
        return None, "bad strikes"
    if strikes >= MAX_STRIKES:
        return None, "too many strikes"
    return "reactivated", base_fee // 2


_STATUS_PLANS = {
    "active": _plan_active,
    "lapsed": _plan_lapsed,
    "suspended": _plan_suspended,
}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    member = raw_member
    payment = raw_payment
    if not all(k in member for k in ("id", "status", "tier")):
        return {"ok": False, "error": "missing member field"}
    if not all(k in payment for k in ("amount", "method")):
        return {"ok": False, "error": "missing payment field"}
    if not isinstance(member["id"], str) or not member["id"]:
        return {"ok": False, "error": "bad member id"}

    status = member["status"]
    if status == "banned":
        return {"ok": False, "error": "member banned"}

    plan = _STATUS_PLANS.get(status)
    if plan is None:
        return {"ok": False, "error": "unknown status"}

    tier = member["tier"]
    if tier not in TIER_FEES:
        return {"ok": False, "error": "unknown tier"}

    label, extra = plan(member, TIER_FEES[tier])
    if label is None:
        return {"ok": False, "error": extra}

    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return {"ok": False, "error": "bad amount"}
    if payment["method"] not in _METHODS:
        return {"ok": False, "error": "unsupported method"}

    fee = TIER_FEES[tier] + extra
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}

    receipt = f"{payment['method']}:{member['id']}:{label}:{fee}"
    return {"ok": True, "status": label, "fee": fee, "receipt": receipt}

