        return "unknown tier"
    return None


def _check_payment(payment):
    """Reject non-positive or non-integer amounts and unsupported methods."""
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return "bad amount"
    if payment["method"] not in ("card", "transfer"):
        return "unsupported method"
    return None


