    if member["expired_days"] <= GRACE_DAYS:
        fee, action = TIER_FEES[member["tier"]] + LATE_FEE, "renewed"
    else:
        fee, action = TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE, "reinstated"
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return {"ok": True, "status": action, "fee": fee,
            "receipt": _receipt(member, payment, action, fee)}


def _renew_suspended(member, payment):
    if "strikes" not in member or not isinstance(member["strikes"], int) or member["strikes"] < 0:
        return {"ok": False, "error": "bad strikes"}
    if member["strikes"] >= MAX_STRIKES:
        return {"ok": False, "error": "too many strikes"}
    error = _check_payment(payment)
    if error:
        return {"ok": False, "error": error}
    fee = TIER_FEES[member["tier"]] + TIER_FEES[member["tier"]] // 2
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return {"ok": True, "status": "reactivated", "fee": fee,
            "receipt": _receipt(member, payment, "reactivated", fee)}


_HANDLERS = {
    "active": _renew_active,
    "lapsed": _renew_lapsed,
    "suspended": _renew_suspended,
}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    error = _validate_shape(raw_member, raw_payment)
    if error:
        return {"ok": False, "error": error}
    status = raw_member["status"]
