GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}
VALID_METHODS = {"card", "transfer"}

# Per-status job: the extra field to validate and the status/charge scheme.
# The fee and outcome status are derived per status, then the shared payment
# checks and receipt building run once.
STATUS_PLAN = {
    "active": {"field": None, "kind": "plain", "outcome": "renewed"},
    "lapsed": {"field": "expired_days", "kind": "grace", "outcome": None},
    "suspended": {"field": "strikes", "kind": "surcharge", "outcome": "reactivated"},
}


def _bad_field(member, field: str, ceil: bool = False) -> bool:
    """True when a status-specific integer field is missing or malformed."""
    value = member.get(field)
    if not isinstance(value, int) or value < 0:
        return True
    return value >= MAX_STRIKES if ceil else False


def _plan(status: str) -> dict | None:
    return STATUS_PLAN.get(status)


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    member = raw_member
    payment = raw_payment
    if "id" not in member or "status" not in member or "tier" not in member:
        return {"ok": False, "error": "missing member field"}
    if "amount" not in payment or "method" not in payment:
        return {"ok": False, "error": "missing payment field"}
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return {"ok": False, "error": "bad member id"}

    status = member["status"]
    if status == "banned":
        return {"ok": False, "error": "member banned"}

    plan = STATUS_PLAN.get(status)
    if plan is None:
        return {"ok": False, "error": "unknown status"}
    if member["tier"] not in TIER_FEES:
        return {"ok": False, "error": "unknown tier"}

    field = plan["field"]
    if field is not None:
        if field == "expired_days":
            if _bad_field(member, "expired_days"):
                return {"ok": False, "error": "bad expiry"}
        else:  # strikes
            if _bad_field(member, "strikes"):
                return {"ok": False, "error": "bad strikes"}
            if member["strikes"] >= MAX_STRIKES:
                return {"ok": False, "error": "too many strikes"}

    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return {"ok": False, "error": "bad amount"}
    if payment["method"] not in VALID_METHODS:
        return {"ok": False, "error": "unsupported method"}

    base_fee = TIER_FEES[member["tier"]]
    kind = plan["kind"]
    if kind == "plain":
        fee = base_fee
        outcome = "renewed"
    elif kind == "grace":
        late = member["expired_days"] > GRACE_DAYS
        fee = base_fee + (REINSTATE_SURCHARGE if late else LATE_FEE)
        outcome = "reinstated" if late else "renewed"
    else:  # surcharge
        fee = base_fee + base_fee // 2
        outcome = "reactivated"

    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}

    receipt = payment["method"] + ":" + member["id"] + ":" + outcome + ":" + str(fee)
    return {"ok": True, "status": outcome, "fee": fee, "receipt": receipt}

