def _positive_int(member: dict, field: str, error: str) -> str | None:
    value = member.get(field)
    if not isinstance(value, int) or value < 0:
        return error
    return None


def _receipt(method: str, mid: str, outcome: str, fee: int) -> str:
    return f"{method}:{mid}:{outcome}:{fee}"


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
