    if status == "active":
        if (err := _validate_tier(member)) is not None:
            return {"ok": False, "error": err}
        if (err := _validate_payment(payment)) is not None:
            return {"ok": False, "error": err}
        fee = TIER_FEES[member["tier"]]
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        return {"ok": True, "status": "renewed", "fee": fee,
                "receipt": _receipt(payment["method"], member["id"], "renewed", fee)}

    if status == "lapsed":
        if (err := _validate_tier(member)) is not None:
            return {"ok": False, "error": err}
        if (err := _positive_int(member, "expired_days", "bad expiry")) is not None:
            return {"ok": False, "error": err}
        if (err := _validate_payment(payment)) is not None:
            return {"ok": False, "error": err}
        if member["expired_days"] <= GRACE_DAYS:
            fee = TIER_FEES[member["tier"]] + LATE_FEE
            new_status = "renewed"
        else:
            fee = TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE
            new_status = "reinstated"
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        return {"ok": True, "status": new_status, "fee": fee,
                "receipt": _receipt(payment["method"], member["id"], new_status, fee)}

    if status == "suspended":
        if (err := _validate_tier(member)) is not None:
            return {"ok": False, "error": err}
        if (err := _positive_int(member, "strikes", "bad strikes")) is not None:
            return {"ok": False, "error": err}
        if member["strikes"] >= MAX_STRIKES:
