GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}

_METHODS = {"card", "transfer"}
_PAYABLE_STATUSES = ("active", "lapsed", "suspended")


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    member = raw_member
    payment = raw_payment
    if "id" not in member or "status" not in member or "tier" not in member:
        return {"ok": False, "error": "missing member field"}
    if "amount" not in payment or "method" not in payment:
        return {"ok": False, "error": "missing payment field"}
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return {"ok": False, "error": "bad member id"}

    status = member["status"]
    if status == "banned":
        return {"ok": False, "error": "member banned"}
    if status not in _PAYABLE_STATUSES:
        return {"ok": False, "error": "unknown status"}

    # Tier is validated first, before any status-specific or payment checks, to
    # match the original per-branch ordering.
    if member["tier"] != "basic" and member["tier"] != "gold":
        return {"ok": False, "error": "unknown tier"}

    # Status-specific fields are validated before the payment checks.
    if status == "lapsed":
        if "expired_days" not in member or not isinstance(member["expired_days"], int) or member["expired_days"] < 0:
            return {"ok": False, "error": "bad expiry"}
    elif status == "suspended":
        if "strikes" not in member or not isinstance(member["strikes"], int) or member["strikes"] < 0:
            return {"ok": False, "error": "bad strikes"}
        if member["strikes"] >= MAX_STRIKES:
            return {"ok": False, "error": "too many strikes"}

    # Payment fields are validated last (amount before method) as in the
    # original per-branch ordering.
    payment_error = _validate_payment(payment)
    if payment_error is not None:
        return {"ok": False, "error": payment_error}

    base_fee = TIER_FEES[member["tier"]]

    if status == "active":
        fee = base_fee
        new_status = "renewed"
    elif status == "lapsed":
        if member["expired_days"] <= GRACE_DAYS:
            fee = base_fee + LATE_FEE
            new_status = "renewed"
        else:
            fee = base_fee + REINSTATE_SURCHARGE
            new_status = "reinstated"
    else:  # suspended
        fee = base_fee + base_fee // 2
        new_status = "reactivated"

    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return _success(member, new_status, fee, payment)


def _validate_payment(payment: dict) -> str | None:
    """Return an error string for the payment checks shared by all payable
    statuses, or None if the payment passes both checks."""
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return "bad amount"
    if payment["method"] not in _METHODS:
        return "unsupported method"
    return None


def _success(member: dict, new_status: str, fee: int, payment: dict) -> dict:
    """Build an idempotent success result and a deterministic receipt string."""
    receipt = payment["method"] + ":" + member["id"] + ":" + new_status + ":" + str(fee)
    return {"ok": True, "status": new_status, "fee": fee, "receipt": receipt}

