# decided by which threshold it clears, so the ladder collapses to a lookup.
LABELS = ("clean", "minor", "moderate", "severe", "invalid")
DEVIATION_BANDS = (3, 6, 12)  # hard_limit is appended at classify time
SCORES = {"clean": 0, "minor": 3, "moderate": 10, "severe": 25, "invalid": 100}


def qc_series(raw: object) -> dict:
    error = _validate_input(raw)
    if error is not None:
        return {"ok": False, "error": error}
    values = raw["values"]
    timestamps = raw["timestamps"]
