    return counts


def _trend(values: list) -> str:
    delta = values[-1] - values[0]
    if delta > TREND_TOLERANCE:
        return "rising"
    if delta < -TREND_TOLERANCE:
        return "falling"
    return "stable"


def _longest_run(labels: list) -> int:
    longest = 0
    current = 0
    for label in labels:
        if label == "clean":
            current = 0
        else:
            current = current + 1
            longest = max(longest, current)
    return longest


def _verdict(total: int) -> str:
