export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface Plan {
  name: string;
  rate: number;
  high: number; // per-night high-season surcharge
  maxNights: number; // minimum nights is always 1
  maxGuests: number;
  minStay?: number; // villa only
  guestFee?: number; // suite only: charged per extra guest over 2
  flatFee?: number; // villa only
}

const PLANS: Record<string, Plan> = {
  standard: { name: "standard", rate: 80, high: 30, maxNights: 14, maxGuests: 2 },
  suite: { name: "suite", rate: 150, high: 60, maxNights: 21, maxGuests: 4, guestFee: 25 },
  villa: { name: "villa", rate: 300, high: 120, maxNights: 28, maxGuests: 8, minStay: 3, flatFee: 500 },
};

function inBounds(value: unknown, min: number, max: number): boolean {
  return Number.isInteger(value) && (value as number) >= min && (value as number) <= max;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!inBounds(req.loyaltyYears, 0, Number.POSITIVE_INFINITY)) {
    return { ok: false, error: "bad loyalty" };
  }

  const plan = PLANS[String(req.category)];
  if (!plan) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights as number;
  const guests = req.guests as number;

  if (!inBounds(nights, 1, plan.maxNights)) {
    return { ok: false, error: "bad nights" };
  }
  if (plan.minStay && nights < plan.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!inBounds(guests, 1, plan.maxGuests)) {
    return { ok: false, error: "bad guests" };
  }
  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  const lofty = req.coupon === "VIP" || (req.loyaltyYears as number) >= 3;

  let total = plan.rate * nights;
  if (req.season === "high") {
    total += plan.high * nights;
  }
  if (lofty) {
    total -= Math.floor(total / 10);
  }
  if (plan.guestFee && guests > 2) {
    total += plan.guestFee;
  }
  if (plan.flatFee) {
    total += plan.flatFee;
  }

  const policy = lofty ? "flex" : "strict";
  const line = plan.name + ":" + String(nights) + "n:" + String(total) + ":" + policy;
  return { ok: true, total, policy, line };
}

