interface CategoryRules {
  maxNights: number;
  maxGuests: number;
  rate: number; // per-night base rate
  peakRate: number; // extra per night during high season
  minStay?: number; // optional minimum stay (villa); produces a dedicated error
  guestSurcharge?: number; // flat fee when guests exceed the threshold (suite)
  guestSurchargeThreshold?: number;
  fixedFee?: number; // flat fee always added (villa)
}

const CATEGORIES: Record<Category, CategoryRules> = {
  standard: { maxNights: 14, maxGuests: 2, rate: 80, peakRate: 30 },
  suite: {
