export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Category = "standard" | "suite" | "villa";

interface CategorySpec {
  /** Base price per night. */
  baseRate: number;
  /** Extra per night charged in the high season. */
  highSeasonRate: number;
  /** Inclusive maximum number of nights allowed. */
  maxNights: number;
  /** Inclusive maximum number of guests allowed. */
  maxGuests: number;
  /** Optional minimum number of nights a booking must satisfy. */
  minNights?: number;
  /** Optaional minimum-stay error message (overrides the generic max-nights error). */
  minStayError?: string;
  /** Flat fee added to the total, if any. */
  fixedFee?: number;
  /** Surcharge applied when more guests than this book. */
  extraGuestOver?: number;
  /** Flat surcharge per such booking. */
  extraGuestFee?: number;
}

const CATEGORIES: Record<Category, CategorySpec> = {
  standard: {
    baseRate: 80,
    highSeasonRate: 30,
    maxNights: 14,
    maxGuests: 2,
  },
  suite: {
    baseRate: 150,
    highSeasonRate: 60,
    maxNights: 21,
    maxGuests: 4,
    extraGuestOver: 2,
    extraGuestFee: 25,
  },
  villa: {
    baseRate: 300,
    highSeasonRate: 120,
    maxNights: 28,
    maxGuests: 8,
    minNights: 3,
    minStayError: "villa minimum stay",
    fixedFee: 500,
  },
};

const VALID_SEASONS = new Set(["low", "high"]);

/** A guest qualifies for the loyalty discount when they've been a member this long. */
const LOYALTY_DISCOUNT_YEARS = 3;
/** A guest qualifies for the flexible policy when they've been a member this long. */
const LOYALTY_FLEX_YEARS = 3;

/** Reduce the total by a 10% rounded-down loyalty discount. */
function applyLoyaltyDiscount(total: number): number {
  return total - Math.floor(total / 10);
}

/** Whether a booking is eligible for the 10% loyalty discount. */
function hasLoyaltyDiscount(
  loyaltyYears: number,
  coupon: string | undefined,
): boolean {
  return loyaltyYears >= LOYALTY_DISCOUNT_YEARS || coupon === "VIP";
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const loyaltyYears = req.loyaltyYears;
  if (typeof loyaltyYears !== "number" || !Number.isInteger(loyaltyYears) || loyaltyYears < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  const loyalty = loyaltyYears as number;

  const category = req.category as string;
  const spec = (CATEGORIES as Record<string, CategorySpec | undefined>)[category];
  if (!spec) {
    return { ok: false, error: "unknown category" };
  }

  // Validate nights within the category's limits (and any minimum stay).
  if (typeof req.nights !== "number" || !Number.isInteger(req.nights) || req.nights < 1 || req.nights > spec.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  const nights = req.nights as number;
  if (spec.minNights !== undefined && nights < spec.minNights) {
    return { ok: false, error: spec.minStayError ?? "villa minimum stay" };
  }

  if (typeof req.guests !== "number" || !Number.isInteger(req.guests) || req.guests < 1 || req.guests > spec.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  const guests = req.guests as number;

  const season = req.season as string;
  if (!VALID_SEASONS.has(season)) {
    return { ok: false, error: "bad season" };
  }

  const coupon = typeof req.coupon === "string" ? req.coupon : undefined;

  // Build the total.
  let total = spec.baseRate * nights;
  if (season === "high") {
    total += spec.highSeasonRate * nights;
  }
  if (hasLoyaltyDiscount(loyalty, coupon)) {
    total = applyLoyaltyDiscount(total);
  }
  if (spec.extraGuestOver !== undefined && guests > spec.extraGuestOver) {
    total += spec.extraGuestFee ?? 0;
  }
  if (spec.fixedFee) {
    total += spec.fixedFee;
  }

  // Determine the cancellation policy.
  let policy = "strict";
  if (coupon === "VIP" || loyalty > LOYALTY_FLEX_YEARS - 1) {
    policy = "flex";
  }

  const line = `${category}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

/**
 * Per-category configuration. All of the numeric rules (base nightly rate,
 * high-season surcharge, maximum nights/guests, minimum stay and any extra
 * one-off fee) live in one table instead of being scattered across three
 * duplicated branches.
 */
interface CategoryConfig {
  readonly minimumStay: number;
  readonly maxNights: number;
  readonly maxGuests: number;
  readonly baseRate: number;
  readonly highSeasonAdd: number;
  /** Optional one-off fee applied after the loyalty discount. */
  readonly extraFee: (guests: number) => number;
}

const MIN_NIGHTS = 1;
const MIN_GUESTS = 1;
const LOYALTY_DISCOUNT_AFTER_YEARS = 3;
const DISCOUNT_FACTOR = 10;

const CATEGORIES: Readonly<Record<string, CategoryConfig>> = {
  standard: {
    minimumStay: 1,
    maxNights: 14,
    maxGuests: 2,
    baseRate: 80,
    highSeasonAdd: 30,
    extraFee: () => 0,
  },
  suite: {
    minimumStay: 1,
    maxNights: 21,
    maxGuests: 4,
    baseRate: 150,
    highSeasonAdd: 60,
    extraFee: (guests) => (guests > 2 ? 25 : 0),
  },
  villa: {
    minimumStay: 3,
    maxNights: 28,
    maxGuests: 8,
    baseRate: 300,
    highSeasonAdd: 120,
    extraFee: () => 500,
  },
};

const isInteger = (value: unknown): value is number => Number.isInteger(value);
const isSeason = (value: unknown): boolean => value === "low" || value === "high";
const isHighSeason = (value: unknown): boolean => value === "high";

/** True when a guest qualifies for a 10% discount and a flexible policy. */
function qualifies(loyaltyYears: number, coupon: unknown): boolean {
  return loyaltyYears >= LOYALTY_DISCOUNT_AFTER_YEARS || coupon === "VIP";
}

function quoteResult(
  category: string,
  nights: number,
  total: number,
  policy: string
): QuoteResult {
  return { ok: true, total, policy, line: `${category}:${nights}n:${total}:${policy}` };
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  if (!isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  const loyaltyYears = req.loyaltyYears as number;

  const config = CATEGORIES[req.category as string];
  if (!config) {
    return { ok: false, error: "unknown category" };
  }
  const category = req.category as string;

  if (!isInteger(req.nights) || (req.nights as number) < MIN_NIGHTS || (req.nights as number) > config.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  const nights = req.nights as number;
  if (nights < config.minimumStay) {
    return { ok: false, error: "villa minimum stay" };
  }

  if (!isInteger(req.guests) || (req.guests as number) < MIN_GUESTS || (req.guests as number) > config.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (!isSeason(req.season)) {
    return { ok: false, error: "bad season" };
  }
  const guests = req.guests as number;

  const eligible = qualifies(loyaltyYears, req.coupon);

  let total = config.baseRate * nights;
  if (isHighSeason(req.season)) {
    total += config.highSeasonAdd * nights;
  }
  if (eligible) {
    total -= Math.floor(total / DISCOUNT_FACTOR);
  }
  total += config.extraFee(guests);

  return quoteResult(category, nights, total, eligible ? "flex" : "strict");
}

