interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

// Refill as many queued backorders as the current stock allows. This is the
// same job performed after any event that frees stock (cancel, expire, restock).
function fillPending(state: State): void {
  for (let position = 0; position < state.queue.length; position++) {
    const id = state.queue[position];
    const want = state.pendingWants[id];
    if ((state.stock[want.item] ?? 0) >= want.qty) {
      state.stock[want.item] = (state.stock[want.item] ?? 0) - want.qty;
      state.reserved[id] = { item: want.item, qty: want.qty };
      state.orders[id] = "reserved";
      delete state.pendingWants[id];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

// Dispatch of each event type to its own handler. Returns an error message on
// failure, or null when the event was processed.
const HANDLERS: Record<
  string,
  (state: State, event: Record<string, unknown>) => string | null
> = {
  order: (state, event) => {
    if (typeof event.id !== "string" || event.id.length === 0) return "bad id";
    if (state.orders[event.id] !== undefined) return "duplicate order";
    if (typeof event.item !== "string" || event.item.length === 0) return "bad item";
    if (!Number.isInteger(event.qty) || (event.qty as number) < 1) return "bad qty";
    const available = state.stock[event.item] ?? 0;
    if (available >= (event.qty as number)) {
      state.stock[event.item] = available - (event.qty as number);
      state.reserved[event.id] = { item: event.item, qty: event.qty as number };
      state.orders[event.id] = "reserved";
    } else {
      state.queue.push(event.id);
      state.pendingWants[event.id] = { item: event.item, qty: event.qty as number };
      state.orders[event.id] = "backordered";
    }
    return null;
  },
  cancel: (state, event) => {
    if (typeof event.id !== "string" || event.id.length === 0) return "bad id";
    if (state.reserved[event.id] !== undefined) {
      const holding = state.reserved[event.id];
      state.stock[holding.item] = (state.stock[holding.item] ?? 0) + holding.qty;
      delete state.reserved[event.id];
      state.orders[event.id] = "cancelled";
      fillPending(state);
    } else if (state.orders[event.id] === "backordered") {
      state.queue.splice(state.queue.indexOf(event.id), 1);
      delete state.pendingWants[event.id];
      state.orders[event.id] = "cancelled";
    } else {
      state.rejected = state.rejected + 1;
    }
    return null;
  },
  ship: (state, event) => {
    if (typeof event.id !== "string" || event.id.length === 0) return "bad id";
    if (
      event.qty !== undefined &&
      (!Number.isInteger(event.qty) || (event.qty as number) < 1)
    ) {
      return "bad qty";
    }
    const holding = state.reserved[event.id];
    if (holding === undefined) {
      state.rejected = state.rejected + 1;
    } else if (event.qty === undefined || (event.qty as number) === holding.qty) {
      delete state.reserved[event.id];
      state.orders[event.id] = "shipped";
    } else if ((event.qty as number) < holding.qty) {
      state.reserved[event.id].qty = holding.qty - (event.qty as number);
      state.orders[event.id] = "partial";
    } else {
      state.rejected = state.rejected + 1;
    }
    return null;
  },
  restock: (state, event) => {
    if (typeof event.item !== "string" || event.item.length === 0) return "bad item";
    if (!Number.isInteger(event.qty) || (event.qty as number) < 1) return "bad qty";
    state.stock[event.item] = (state.stock[event.item] ?? 0) + (event.qty as number);
    fillPending(state);
    return null;
  },
  expire: (state, event) => {
    if (typeof event.id !== "string" || event.id.length === 0) return "bad id";
    if (state.reserved[event.id] !== undefined) {
      const holding = state.reserved[event.id];
      state.stock[holding.item] = (state.stock[holding.item] ?? 0) + holding.qty;
      delete state.reserved[event.id];
      state.orders[event.id] = "expired";
      fillPending(state);
    } else {
      state.rejected = state.rejected + 1;
    }
    return null;
  },
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const state: State = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const handle = HANDLERS[event.type as string];
    if (handle === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const trouble = handle(state, event);
    if (trouble !== null) {
      return { ok: false, error: "event " + index + ": " + trouble };
    }
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

/** Mutable working state threaded through the event handlers. */
interface FulfillState {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

/** The fields an event carries, read loosely from the raw payload. */
interface EventFields {
  id?: string;
  item?: string;
  qty?: number;
}

/** One event handler: mutates state, returns an error reason or undefined. */
type Handler = (ev: EventFields, state: FulfillState) => string | undefined;

// Dispatch by event type - collapses the per-type branch chain into a lookup.
const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const state: FulfillState = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  for (let index = 0; index < input.events.length; index++) {
    const rawEvent = input.events[index];
    if (typeof rawEvent !== "object" || rawEvent === null) {
      return fail("event " + index + ": ", "malformed");
    }
    const ev = rawEvent as Record<string, unknown>;
    const handler = HANDLERS[ev.type as string];
    if (handler === undefined) {
      return fail("event " + index + ": ", "bad type");
    }
    const error = handler(ev as EventFields, state);
    if (error !== undefined) {
      return fail("event " + index + ": ", error);
    }
  }

  return {
    ok: true,
    orders: state.orders,
    stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

function fail(prefix: string, reason: string): FulfillmentResult {
  return { ok: false, error: prefix + reason };
}

function badId(ev: EventFields): boolean {
  return typeof ev.id !== "string" || ev.id.length === 0;
}

function badItem(ev: EventFields): boolean {
  return typeof ev.item !== "string" || ev.item.length === 0;
}

function badQty(ev: EventFields): boolean {
  return typeof ev.qty !== "number" || !Number.isInteger(ev.qty) || ev.qty < 1;
}

function handleOrder(ev: EventFields, state: FulfillState): string | undefined {
  if (badId(ev)) return "bad id";
  if (state.orders[ev.id as string] !== undefined) return "duplicate order";
  if (badItem(ev)) return "bad item";
  if (badQty(ev)) return "bad qty";
  const want: Want = { item: ev.item as string, qty: ev.qty as number };
  const onHand = state.stock[want.item] ?? 0;
  if (onHand >= want.qty) {
    state.stock[want.item] = onHand - want.qty;
    state.reserved[ev.id as string] = want;
    state.orders[ev.id as string] = "reserved";
  } else {
    state.queue.push(ev.id as string);
    state.pendingWants[ev.id as string] = want;
    state.orders[ev.id as string] = "backordered";
  }
}

function handleCancel(ev: EventFields, state: FulfillState): string | undefined {
  if (badId(ev)) return "bad id";
  if (state.reserved[ev.id as string] !== undefined) {
    const holding = state.reserved[ev.id as string];
    state.stock[holding.item] = (state.stock[holding.item] ?? 0) + holding.qty;
    delete state.reserved[ev.id as string];
    state.orders[ev.id as string] = "cancelled";
    fillQueue(state);
  } else if (state.orders[ev.id as string] === "backordered") {
    state.queue.splice(state.queue.indexOf(ev.id as string), 1);
    delete state.pendingWants[ev.id as string];
    state.orders[ev.id as string] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
}

function handleShip(ev: EventFields, state: FulfillState): string | undefined {
  if (badId(ev)) return "bad id";
  if (ev.qty !== undefined && badQty(ev)) return "bad qty";
  const holding = state.reserved[ev.id as string];
  if (holding === undefined) {
    state.rejected = state.rejected + 1;
  } else if (ev.qty === undefined || ev.qty === holding.qty) {
    delete state.reserved[ev.id as string];
    state.orders[ev.id as string] = "shipped";
  } else if (ev.qty < holding.qty) {
    holding.qty = holding.qty - ev.qty;
    state.orders[ev.id as string] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
}

function handleRestock(ev: EventFields, state: FulfillState): string | undefined {
  if (badItem(ev)) return "bad item";
  if (badQty(ev)) return "bad qty";
  state.stock[ev.item as string] = (state.stock[ev.item as string] ?? 0) + (ev.qty as number);
  fillQueue(state);
}

function handleExpire(ev: EventFields, state: FulfillState): string | undefined {
  if (badId(ev)) return "bad id";
  if (state.reserved[ev.id as string] !== undefined) {
    const holding = state.reserved[ev.id as string];
    state.stock[holding.item] = (state.stock[holding.item] ?? 0) + holding.qty;
    delete state.reserved[ev.id as string];
    state.orders[ev.id as string] = "expired";
    fillQueue(state);
  } else {
    state.rejected = state.rejected + 1;
  }
}

/** Refill waiting backorders with newly available stock. */
function fillQueue(state: FulfillState): void {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    const onHand = state.stock[want.item] ?? 0;
    if (onHand >= want.qty) {
      state.stock[want.item] = onHand - want.qty;
      state.reserved[pendingId] = { item: want.item, qty: want.qty };
      state.orders[pendingId] = "reserved";
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

// Mutable state threaded through the event handlers.
interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

// Stock is absent for any item we have never seen; treat it as zero.
function onHand(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

// Give available stock to the earliest pending backorders.
function fillBackorders(state: State): void {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    const available = onHand(state.stock, want.item);
    if (available < want.qty) {
      continue;
    }
    state.stock[want.item] = available - want.qty;
    state.reserved[pendingId] = { item: want.item, qty: want.qty };
    state.orders[pendingId] = "reserved";
    delete state.pendingWants[pendingId];
    state.queue.splice(position, 1);
    position = position - 1;
  }
}

// Return a reserved order's stock, mark it released, then refill backorders.
function releaseHolding(state: State, id: string, status: string): void {
  const holding = state.reserved[id];
  state.stock[holding.item] = onHand(state.stock, holding.item) + holding.qty;
  delete state.reserved[id];
  state.orders[id] = status;
  fillBackorders(state);
}

type Handler = (state: State, event: Record<string, unknown>, index: number) => string | undefined;

function handleOrder(state: State, event: Record<string, unknown>, index: number): string | undefined {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (state.orders[event.id] !== undefined) {
    return "event " + index + ": duplicate order";
  }
  if (typeof event.item !== "string" || event.item.length === 0) {
    return "event " + index + ": bad item";
  }
  if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
    return "event " + index + ": bad qty";
  }
  const available = onHand(state.stock, event.item);
  if (available >= (event.qty as number)) {
    state.stock[event.item] = available - (event.qty as number);
    state.reserved[event.id] = { item: event.item, qty: event.qty as number };
    state.orders[event.id] = "reserved";
  } else {
    state.queue.push(event.id);
    state.pendingWants[event.id] = { item: event.item, qty: event.qty as number };
    state.orders[event.id] = "backordered";
  }
  return undefined;
}

function handleCancel(state: State, event: Record<string, unknown>, index: number): string | undefined {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (state.reserved[event.id] !== undefined) {
    releaseHolding(state, event.id, "cancelled");
  } else if (state.orders[event.id] === "backordered") {
    state.queue.splice(state.queue.indexOf(event.id), 1);
    delete state.pendingWants[event.id];
    state.orders[event.id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
  return undefined;
}

function handleShip(state: State, event: Record<string, unknown>, index: number): string | undefined {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
    return "event " + index + ": bad qty";
  }
  if (state.reserved[event.id] === undefined) {
    state.rejected = state.rejected + 1;
  } else if (event.qty === undefined || (event.qty as number) === state.reserved[event.id].qty) {
    delete state.reserved[event.id];
    state.orders[event.id] = "shipped";
  } else if ((event.qty as number) < state.reserved[event.id].qty) {
    state.reserved[event.id].qty = state.reserved[event.id].qty - (event.qty as number);
    state.orders[event.id] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
  return undefined;
}

function handleRestock(state: State, event: Record<string, unknown>, index: number): string | undefined {
  if (typeof event.item !== "string" || event.item.length === 0) {
    return "event " + index + ": bad item";
  }
  if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
    return "event " + index + ": bad qty";
  }
  state.stock[event.item] = onHand(state.stock, event.item) + (event.qty as number);
  fillBackorders(state);
  return undefined;
}

function handleExpire(state: State, event: Record<string, unknown>, index: number): string | undefined {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (state.reserved[event.id] !== undefined) {
    releaseHolding(state, event.id, "expired");
  } else {
    state.rejected = state.rejected + 1;
  }
  return undefined;
}

// Dispatch on event type instead of an if/else-if chain.
const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const state: State = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const handler = HANDLERS[event.type as string];
    if (!handler) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const error = handler(state, event, index);
    if (error) {
      return { ok: false, error: error };
    }
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

