interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

type Handler = (state: State, event: Record<string, unknown>, ctx: string) => string | null;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function stockOf(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

function readStock(raw: unknown): Record<string, number> | null {
  if (!isObject(raw)) {
    return null;
  }
  const stock: Record<string, number> = {};
  const src = raw as Record<string, unknown>;
  for (const item of Object.keys(src)) {
    if (!Number.isInteger(src[item]) || (src[item] as number) < 0) {
      return null;
    }
    stock[item] = src[item] as number;
  }
  return stock;
}

function need(when: unknown, ctx: string, what: string): string | null {
  return when ? ctx + what : null;
}

function idError(event: Record<string, unknown>, ctx: string): string | null {
  return need(typeof event.id !== "string" || event.id.length === 0, ctx, "bad id");
}

function itemError(event: Record<string, unknown>, ctx: string): string | null {
  return need(typeof event.item !== "string" || event.item.length === 0, ctx, "bad item");
}

function qtyError(event: Record<string, unknown>, ctx: string): string | null {
  return need(
    !Number.isInteger(event.qty) || (event.qty as number) < 1,
    ctx,
    "bad qty",
  );
}

// After freeing stock (cancel/expire) or adding stock (restock), fulfill any
// backorder queue entries that can now be met.
function fillQueue(state: State): void {
  for (let position = 0; position < state.queue.length; position++) {
    const id = state.queue[position];
    const want = state.pendingWants[id];
    const onHand = stockOf(state.stock, want.item);
    if (onHand >= want.qty) {
      state.stock[want.item] = onHand - want.qty;
      state.reserved[id] = { item: want.item, qty: want.qty };
      state.orders[id] = "reserved";
      delete state.pendingWants[id];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function release(state: State, id: string, status: string): void {
  const holding = state.reserved[id];
  state.stock[holding.item] = stockOf(state.stock, holding.item) + holding.qty;
  delete state.reserved[id];
  state.orders[id] = status;
}

function handleOrder(state: State, event: Record<string, unknown>, ctx: string): string | null {
  const badId = idError(event, ctx);
  if (badId) {
    return badId;
  }
  if (state.orders[event.id as string] !== undefined) {
    return ctx + "duplicate order";
  }
  const badItem = itemError(event, ctx);
  if (badItem) {
    return badItem;
  }
  const badQty = qtyError(event, ctx);
  if (badQty) {
    return badQty;
  }
  const want: Want = { item: event.item as string, qty: event.qty as number };
  const onHand = stockOf(state.stock, want.item);
  if (onHand >= want.qty) {
    state.stock[want.item] = onHand - want.qty;
    state.reserved[event.id as string] = want;
    state.orders[event.id as string] = "reserved";
  } else {
    state.queue.push(event.id as string);
    state.pendingWants[event.id as string] = want;
    state.orders[event.id as string] = "backordered";
  }
  return null;
}

function handleCancel(state: State, event: Record<string, unknown>, ctx: string): string | null {
  const badId = idError(event, ctx);
  if (badId) {
    return badId;
  }
  if (state.reserved[event.id as string] !== undefined) {
    release(state, event.id as string, "cancelled");
    fillQueue(state);
  } else if (state.orders[event.id as string] === "backordered") {
    state.queue.splice(state.queue.indexOf(event.id as string), 1);
    delete state.pendingWants[event.id as string];
    state.orders[event.id as string] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function handleShip(state: State, event: Record<string, unknown>, ctx: string): string | null {
  const badId = idError(event, ctx);
  if (badId) {
    return badId;
  }
  const qty = event.qty;
  if (qty !== undefined && (!Number.isInteger(qty) || (qty as number) < 1)) {
    return ctx + "bad qty";
  }
  const held = state.reserved[event.id as string];
  if (held === undefined) {
    state.rejected = state.rejected + 1;
  } else if (qty === undefined || (qty as number) === held.qty) {
    delete state.reserved[event.id as string];
    state.orders[event.id as string] = "shipped";
  } else if ((qty as number) < held.qty) {
    held.qty = held.qty - (qty as number);
    state.orders[event.id as string] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function handleRestock(state: State, event: Record<string, unknown>, ctx: string): string | null {
  const badItem = itemError(event, ctx);
  if (badItem) {
    return badItem;
  }
  const badQty = qtyError(event, ctx);
  if (badQty) {
    return badQty;
  }
  state.stock[event.item as string] = stockOf(state.stock, event.item as string) + (event.qty as number);
  fillQueue(state);
  return null;
}

function handleExpire(state: State, event: Record<string, unknown>, ctx: string): string | null {
  const badId = idError(event, ctx);
  if (badId) {
    return badId;
  }
  if (state.reserved[event.id as string] !== undefined) {
    release(state, event.id as string, "expired");
    fillQueue(state);
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (!isObject(raw)) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  const stock = readStock(input.stock);
  if (!stock) {
    return { ok: false, error: "bad stock" };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const state: State = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (!isObject(event)) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const handler = HANDLERS[event.type as string];
    if (!handler) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const err = handler(state, event, "event " + index + ": ");
    if (err) {
      return { ok: false, error: err };
    }
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

type Event = Record<string, unknown>;

/** Mutable state threaded through every event handler. */
interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

const onHand = (stock: Record<string, number>, item: string): number =>
  stock[item] === undefined ? 0 : stock[item];

const badEvent = (index: number, reason: string): string =>
  "event " + index + ": " + reason;

// --- field validation: return a bad-event message, or undefined when the field is present ---
const requireId = (event: Event, index: number): string | undefined =>
  typeof event.id !== "string" || event.id.length === 0 ? badEvent(index, "bad id") : undefined;

const requireItem = (event: Event, index: number): string | undefined =>
  typeof event.item !== "string" || event.item.length === 0 ? badEvent(index, "bad item") : undefined;

const requireQty = (event: Event, index: number): string | undefined =>
  !Number.isInteger(event.qty) || (event.qty as number) < 1 ? badEvent(index, "bad qty") : undefined;

const requireOptionalQty = (event: Event, index: number): string | undefined =>
  event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)
    ? badEvent(index, "bad qty")
    : undefined;

/** Release freed stock into backordered orders in FIFO order. */
function fulfillBackorders(state: State): void {
  for (let position = 0; position < state.queue.length; position++) {
    const id = state.queue[position];
    const want = state.pendingWants[id];
    if (onHand(state.stock, want.item) >= want.qty) {
      state.stock[want.item] = onHand(state.stock, want.item) - want.qty;
      state.reserved[id] = { item: want.item, qty: want.qty };
      state.orders[id] = "reserved";
      delete state.pendingWants[id];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function onOrder(state: State, index: number, event: Event): string | undefined {
  const err =
    requireId(event, index) ||
    requireItem(event, index) ||
    requireQty(event, index);
  if (err) return err;
  if (state.orders[event.id as string] !== undefined) return badEvent(index, "duplicate order");
  const item = event.item as string;
  const qty = event.qty as number;
  if (onHand(state.stock, item) >= qty) {
    state.stock[item] = onHand(state.stock, item) - qty;
    state.reserved[event.id as string] = { item, qty };
    state.orders[event.id as string] = "reserved";
  } else {
    state.queue.push(event.id as string);
    state.pendingWants[event.id as string] = { item, qty };
    state.orders[event.id as string] = "backordered";
  }
}

function onCancel(state: State, index: number, event: Event): string | undefined {
  const err = requireId(event, index);
  if (err) return err;
  const id = event.id as string;
  if (state.reserved[id] !== undefined) {
    const holding = state.reserved[id];
    state.stock[holding.item] = onHand(state.stock, holding.item) + holding.qty;
    delete state.reserved[id];
    state.orders[id] = "cancelled";
    fulfillBackorders(state);
  } else if (state.orders[id] === "backordered") {
    state.queue.splice(state.queue.indexOf(id), 1);
    delete state.pendingWants[id];
    state.orders[id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
}

function onShip(state: State, index: number, event: Event): string | undefined {
  const err = requireId(event, index) || requireOptionalQty(event, index);
  if (err) return err;
  const id = event.id as string;
  if (state.reserved[id] === undefined) {
    state.rejected = state.rejected + 1;
  } else if (event.qty === undefined || (event.qty as number) === state.reserved[id].qty) {
    delete state.reserved[id];
    state.orders[id] = "shipped";
  } else if ((event.qty as number) < state.reserved[id].qty) {
    state.reserved[id].qty = state.reserved[id].qty - (event.qty as number);
    state.orders[id] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
}

function onRestock(state: State, index: number, event: Event): string | undefined {
  const err = requireItem(event, index) || requireQty(event, index);
  if (err) return err;
  state.stock[event.item as string] = onHand(state.stock, event.item as string) + (event.qty as number);
  fulfillBackorders(state);
}

function onExpire(state: State, index: number, event: Event): string | undefined {
  const err = requireId(event, index);
  if (err) return err;
  const id = event.id as string;
  if (state.reserved[id] !== undefined) {
    const holding = state.reserved[id];
    state.stock[holding.item] = onHand(state.stock, holding.item) + holding.qty;
    delete state.reserved[id];
    state.orders[id] = "expired";
    fulfillBackorders(state);
  } else {
    state.rejected = state.rejected + 1;
  }
}

const HANDLERS: Record<string, (state: State, index: number, event: Event) => string | undefined> = {
  order: onOrder,
  cancel: onCancel,
  ship: onShip,
  restock: onRestock,
  expire: onExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const state: State = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Event;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: badEvent(index, "malformed") };
    }
    const handle = HANDLERS[event.type as string];
    if (handle === undefined) {
      return { ok: false, error: badEvent(index, "bad type") };
    }
    const err = handle(state, index, event);
    if (err) {
      return { ok: false, error: err };
    }
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

type ErrorMessage = string | undefined;

/** Mutable state threaded through every event handler. */
interface Ctx {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  queue: string[];
  pendingWants: Record<string, Want>;
  rejected: number;
}

/* ------------------------------------------------------------------ */
/* Validation helpers: the same two checks appear on id/item/qty in    */
/* several handlers, so each lives here once instead of inline copies. */
/* ------------------------------------------------------------------ */

function requireId(event: Record<string, unknown>): ErrorMessage {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "bad id";
  }
  return undefined;
}

function requireItem(event: Record<string, unknown>): ErrorMessage {
  if (typeof event.item !== "string" || event.item.length === 0) {
    return "bad item";
  }
  return undefined;
}

function requireQty(event: Record<string, unknown>): ErrorMessage {
  if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
    return "bad qty";
  }
  return undefined;
}

/* ------------------------------------------------------------------ */
/* Shared state transitions.                                           */
/* ------------------------------------------------------------------ */

/** Put a reserved order's stock back on the shelf, marking its status. */
function release(
  id: string,
  status: string,
  ctx: Ctx,
): void {
  const held = ctx.reserved[id];
  ctx.stock[held.item] = (ctx.stock[held.item] ?? 0) + held.qty;
  delete ctx.reserved[id];
  ctx.orders[id] = status;
}

/** Fill as many queued backorders as today's stock allows. */
function fillQueue(ctx: Ctx): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    const onHand = ctx.stock[want.item] ?? 0;
    if (onHand >= want.qty) {
      ctx.stock[want.item] = onHand - want.qty;
      ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
      ctx.orders[pendingId] = "reserved";
      delete ctx.pendingWants[pendingId];
      ctx.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

/* ------------------------------------------------------------------ */
/* One handler per event type: each is a distinct operation.           */
/* ------------------------------------------------------------------ */

function handleOrder(event: Record<string, unknown>, ctx: Ctx): ErrorMessage {
  const idError = requireId(event);
  if (idError) {
    return idError;
  }
  const id = event.id as string;
  if (ctx.orders[id] !== undefined) {
    return "duplicate order";
  }
  const itemError = requireItem(event) ?? requireQty(event);
  if (itemError) {
    return itemError;
  }
  const item = event.item as string;
  const qty = event.qty as number;
  const available = ctx.stock[item] ?? 0;
  if (available >= qty) {
    ctx.stock[item] = available - qty;
    ctx.reserved[id] = { item, qty };
    ctx.orders[id] = "reserved";
  } else {
    ctx.queue.push(id);
    ctx.pendingWants[id] = { item, qty };
    ctx.orders[id] = "backordered";
  }
  return undefined;
}

function handleShip(event: Record<string, unknown>, ctx: Ctx): ErrorMessage {
  const idError = requireId(event);
  if (idError) {
    return idError;
  }
  if (
    event.qty !== undefined &&
    (!Number.isInteger(event.qty) || (event.qty as number) < 1)
  ) {
    return "bad qty";
  }
  const id = event.id as string;
  const held = ctx.reserved[id];
  if (held === undefined) {
    ctx.rejected = ctx.rejected + 1;
  } else if (event.qty === undefined || (event.qty as number) === held.qty) {
    delete ctx.reserved[id];
    ctx.orders[id] = "shipped";
  } else if ((event.qty as number) < held.qty) {
    held.qty = held.qty - (event.qty as number);
    ctx.orders[id] = "partial";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return undefined;
}

function handleRestock(event: Record<string, unknown>, ctx: Ctx): ErrorMessage {
  const itemError = requireItem(event) ?? requireQty(event);
  if (itemError) {
    return itemError;
  }
  const item = event.item as string;
  ctx.stock[item] = (ctx.stock[item] ?? 0) + (event.qty as number);
  fillQueue(ctx);
  return undefined;
}

function handleCancel(event: Record<string, unknown>, ctx: Ctx): ErrorMessage {
  const idError = requireId(event);
  if (idError) {
    return idError;
  }
  const id = event.id as string;
  if (ctx.reserved[id] !== undefined) {
    release(id, "cancelled", ctx);
    fillQueue(ctx);
  } else if (ctx.orders[id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(id), 1);
    delete ctx.pendingWants[id];
    ctx.orders[id] = "cancelled";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return undefined;
}

function handleExpire(event: Record<string, unknown>, ctx: Ctx): ErrorMessage {
  const idError = requireId(event);
  if (idError) {
    return idError;
  }
  const id = event.id as string;
  if (ctx.reserved[id] !== undefined) {
    release(id, "expired", ctx);
    fillQueue(ctx);
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return undefined;
}

/* Event-type → handler lookup, replacing a five-arm if/else chain. */
const HANDLERS: Record<
  string,
  (event: Record<string, unknown>, ctx: Ctx) => ErrorMessage
> = {
  order: handleOrder,
  ship: handleShip,
  restock: handleRestock,
  cancel: handleCancel,
  expire: handleExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const ctx: Ctx = {
    stock,
    orders: {},
    reserved: {},
    queue: [],
    pendingWants: {},
    rejected: 0,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const handler = HANDLERS[event.type as string];
    if (!handler) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const err = handler(event, ctx);
    if (err) {
      return { ok: false, error: "event " + index + ": " + err };
    }
  }

  return {
    ok: true,
    orders: ctx.orders,
    stock: ctx.stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

/* ------------------------------------------------------------------ */
/* Reporting: a job entirely separate from event processing.           */
/* ------------------------------------------------------------------ */

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

const onHand = (stock: Record<string, number>, item: string): number =>
  stock[item] === undefined ? 0 : stock[item];

const err = (index: number, reason: string): string => `event ${index}: ${reason}`;

/** Fulfill as many waiting backorders as available stock allows. */
function fillPending(s: State): void {
  for (let position = 0; position < s.queue.length; position++) {
    const pendingId = s.queue[position];
    const want = s.pendingWants[pendingId];
    if (onHand(s.stock, want.item) >= want.qty) {
      s.stock[want.item] = onHand(s.stock, want.item) - want.qty;
      s.reserved[pendingId] = { item: want.item, qty: want.qty };
      s.orders[pendingId] = "reserved";
      delete s.pendingWants[pendingId];
      s.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

type Handler = (s: State, e: Record<string, unknown>, index: number) => string | null;

function handleOrder(s: State, e: Record<string, unknown>, index: number): string | null {
  if (typeof e.id !== "string" || e.id.length === 0) return err(index, "bad id");
  if (s.orders[e.id] !== undefined) return err(index, "duplicate order");
  if (typeof e.item !== "string" || e.item.length === 0) return err(index, "bad item");
  if (!Number.isInteger(e.qty) || (e.qty as number) < 1) return err(index, "bad qty");
  const available = onHand(s.stock, e.item);
  if (available >= (e.qty as number)) {
    s.stock[e.item] = available - (e.qty as number);
    s.reserved[e.id] = { item: e.item, qty: e.qty as number };
    s.orders[e.id] = "reserved";
  } else {
    s.queue.push(e.id);
    s.pendingWants[e.id] = { item: e.item, qty: e.qty as number };
    s.orders[e.id] = "backordered";
  }
  return null;
}

function handleCancel(s: State, e: Record<string, unknown>, index: number): string | null {
  if (typeof e.id !== "string" || e.id.length === 0) return err(index, "bad id");
  const holding = s.reserved[e.id];
  if (holding !== undefined) {
    s.stock[holding.item] = onHand(s.stock, holding.item) + holding.qty;
    delete s.reserved[e.id];
    s.orders[e.id] = "cancelled";
    fillPending(s);
  } else if (s.orders[e.id] === "backordered") {
    s.queue.splice(s.queue.indexOf(e.id), 1);
    delete s.pendingWants[e.id];
    s.orders[e.id] = "cancelled";
  } else {
    s.rejected = s.rejected + 1;
  }
  return null;
}

function handleShip(s: State, e: Record<string, unknown>, index: number): string | null {
  if (typeof e.id !== "string" || e.id.length === 0) return err(index, "bad id");
  if (e.qty !== undefined && (!Number.isInteger(e.qty) || (e.qty as number) < 1)) {
    return err(index, "bad qty");
  }
  const holding = s.reserved[e.id];
  if (holding === undefined) {
    s.rejected = s.rejected + 1;
  } else if (e.qty === undefined || (e.qty as number) === holding.qty) {
    delete s.reserved[e.id];
    s.orders[e.id] = "shipped";
  } else if ((e.qty as number) < holding.qty) {
    holding.qty = holding.qty - (e.qty as number);
    s.orders[e.id] = "partial";
  } else {
    s.rejected = s.rejected + 1;
  }
  return null;
}

function handleRestock(s: State, e: Record<string, unknown>, index: number): string | null {
  if (typeof e.item !== "string" || e.item.length === 0) return err(index, "bad item");
  if (!Number.isInteger(e.qty) || (e.qty as number) < 1) return err(index, "bad qty");
  s.stock[e.item] = onHand(s.stock, e.item) + (e.qty as number);
  fillPending(s);
  return null;
}

function handleExpire(s: State, e: Record<string, unknown>, index: number): string | null {
  if (typeof e.id !== "string" || e.id.length === 0) return err(index, "bad id");
  const holding = s.reserved[e.id];
  if (holding !== undefined) {
    s.stock[holding.item] = onHand(s.stock, holding.item) + holding.qty;
    delete s.reserved[e.id];
    s.orders[e.id] = "expired";
    fillPending(s);
  } else {
    s.rejected = s.rejected + 1;
  }
  return null;
}

const EVENT_HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
