interface Context {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

function stockOf(ctx: Context, item: string): number {
  return ctx.stock[item] === undefined ? 0 : ctx.stock[item];
}

function needId(event: any, index: number): string | undefined {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "event " + index + ": bad id";
  }
  return undefined;
}

function needItem(event: any, index: number): string | undefined {
  if (typeof event.item !== "string" || event.item.length === 0) {
    return "event " + index + ": bad item";
  }
  return undefined;
}

function needQty(event: any, index: number): string | undefined {
  if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
    return "event " + index + ": bad qty";
  }
  return undefined;
}

function fulfillBackorders(ctx: Context): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    const onHand = stockOf(ctx, want.item);
    if (onHand >= want.qty) {
      ctx.stock[want.item] = onHand - want.qty;
      ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
      ctx.orders[pendingId] = "reserved";
      delete ctx.pendingWants[pendingId];
      ctx.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function handleOrder(ctx: Context, event: any, index: number): string | undefined {
  const err = needId(event, index);
  if (err) return err;
  if (ctx.orders[event.id] !== undefined) {
    return "event " + index + ": duplicate order";
  }
  const err2 = needItem(event, index) ?? needQty(event, index);
  if (err2) return err2;
  const available = stockOf(ctx, event.item as string);
  if (available >= (event.qty as number)) {
    ctx.stock[event.item as string] = available - (event.qty as number);
    ctx.reserved[event.id] = { item: event.item as string, qty: event.qty as number };
    ctx.orders[event.id] = "reserved";
  } else {
    ctx.queue.push(event.id);
    ctx.pendingWants[event.id] = { item: event.item as string, qty: event.qty as number };
    ctx.orders[event.id] = "backordered";
  }
  return undefined;
}

function handleCancel(ctx: Context, event: any, index: number): string | undefined {
  const err = needId(event, index);
  if (err) return err;
  if (ctx.reserved[event.id] !== undefined) {
    const holding = ctx.reserved[event.id];
    ctx.stock[holding.item] = stockOf(ctx, holding.item) + holding.qty;
    delete ctx.reserved[event.id];
    ctx.orders[event.id] = "cancelled";
    fulfillBackorders(ctx);
  } else if (ctx.orders[event.id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(event.id), 1);
    delete ctx.pendingWants[event.id];
    ctx.orders[event.id] = "cancelled";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return undefined;
}

function handleShip(ctx: Context, event: any, index: number): string | undefined {
  const err = needId(event, index);
  if (err) return err;
  if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
    return "event " + index + ": bad qty";
  }
  const held = ctx.reserved[event.id];
  if (held === undefined) {
    ctx.rejected = ctx.rejected + 1;
  } else if (event.qty === undefined || (event.qty as number) === held.qty) {
