  } else if ((event.qty as number) < held.qty) {
    held.qty = held.qty - (event.qty as number);
    ctx.orders[event.id] = "partial";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return undefined;
}

function handleRestock(ctx: Context, event: any, index: number): string | undefined {
  const err = needItem(event, index) ?? needQty(event, index);
  if (err) return err;
  ctx.stock[event.item as string] = stockOf(ctx, event.item as string) + (event.qty as number);
  fulfillBackorders(ctx);
  return undefined;
}

function handleExpire(ctx: Context, event: any, index: number): string | undefined {
  const err = needId(event, index);
  if (err) return err;
  if (ctx.reserved[event.id] !== undefined) {
    const holding = ctx.reserved[event.id];
    ctx.stock[holding.item] = stockOf(ctx, holding.item) + holding.qty;
    delete ctx.reserved[event.id];
    ctx.orders[event.id] = "expired";
    fulfillBackorders(ctx);
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return undefined;
}

