/* ------------------------------------------------------------------ *
 *  Shared processing state threaded through every event handler.
 * ------------------------------------------------------------------ */
interface Ctx {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  queue: string[];
  wants: Record<string, Want>;
  rejected: number;
}

type Handler = (ctx: Ctx, event: Record<string, unknown>, index: number) => string | undefined;

/* ------------------------------------------------------------------ *
 *  Small, single-purpose helpers the handlers share.
 * ------------------------------------------------------------------ */

/** Stock on hand for an item, treating a missing key as zero. */
function stockOf(ctx: Ctx, item: string): number {
  return ctx.stock[item] === undefined ? 0 : ctx.stock[item];
}

/** Walk the backorder queue and fill any entries that now fit in stock. */
function fulfillQueue(ctx: Ctx): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const id = ctx.queue[position];
    const want = ctx.wants[id];
    const onHand = stockOf(ctx, want.item);
    if (onHand >= want.qty) {
      ctx.stock[want.item] = onHand - want.qty;
      ctx.reserved[id] = { item: want.item, qty: want.qty };
      ctx.orders[id] = "reserved";
      delete ctx.wants[id];
      ctx.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

/** Add `qty` to an item's stock, then give queued orders first chance at it. */
function addStock(ctx: Ctx, item: string, qty: number): void {
  ctx.stock[item] = stockOf(ctx, item) + qty;
  fulfillQueue(ctx);
}

function badEvent(index: number, why: string): string {
  return "event " + index + ": " + why;
}

/* ------------------------------------------------------------------ *
 *  One handler per event type. Each returns an error message (or
 *  undefined when the event was applied).
 * ------------------------------------------------------------------ */

function handleOrder(ctx: Ctx, e: Record<string, unknown>, i: number): string | undefined {
  if (typeof e.id !== "string" || e.id.length === 0) return badEvent(i, "bad id");
  if (ctx.orders[e.id] !== undefined) return badEvent(i, "duplicate order");
  if (typeof e.item !== "string" || e.item.length === 0) return badEvent(i, "bad item");
  if (!Number.isInteger(e.qty) || (e.qty as number) < 1) return badEvent(i, "bad qty");
  const item = e.item;
  const qty = e.qty as number;
  if (stockOf(ctx, item) >= qty) {
    ctx.stock[item] = stockOf(ctx, item) - qty;
    ctx.reserved[e.id] = { item, qty };
    ctx.orders[e.id] = "reserved";
  } else {
    ctx.queue.push(e.id);
    ctx.wants[e.id] = { item, qty };
    ctx.orders[e.id] = "backordered";
  }
  return undefined;
}

function handleCancel(ctx: Ctx, e: Record<string, unknown>, i: number): string | undefined {
  if (typeof e.id !== "string" || e.id.length === 0) return badEvent(i, "bad id");
  const holding = ctx.reserved[e.id];
  if (holding !== undefined) {
    addStock(ctx, holding.item, holding.qty);
    delete ctx.reserved[e.id];
    ctx.orders[e.id] = "cancelled";
  } else if (ctx.orders[e.id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(e.id), 1);
    delete ctx.wants[e.id];
    ctx.orders[e.id] = "cancelled";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return undefined;
}

function handleShip(ctx: Ctx, e: Record<string, unknown>, i: number): string | undefined {
  if (typeof e.id !== "string" || e.id.length === 0) return badEvent(i, "bad id");
  if (e.qty !== undefined && (!Number.isInteger(e.qty) || (e.qty as number) < 1)) {
    return badEvent(i, "bad qty");
  }
  const holding = ctx.reserved[e.id];
  if (holding === undefined) {
    ctx.rejected = ctx.rejected + 1;
  } else if (e.qty === undefined || (e.qty as number) === holding.qty) {
    delete ctx.reserved[e.id];
    ctx.orders[e.id] = "shipped";
  } else if ((e.qty as number) < holding.qty) {
    holding.qty = holding.qty - (e.qty as number);
    ctx.orders[e.id] = "partial";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return undefined;
}

function handleRestock(ctx: Ctx, e: Record<string, unknown>, i: number): string | undefined {
  if (typeof e.item !== "string" || e.item.length === 0) return badEvent(i, "bad item");
  if (!Number.isInteger(e.qty) || (e.qty as number) < 1) return badEvent(i, "bad qty");
  addStock(ctx, e.item, e.qty as number);
  return undefined;
}

function handleExpire(ctx: Ctx, e: Record<string, unknown>, i: number): string | undefined {
  if (typeof e.id !== "string" || e.id.length === 0) return badEvent(i, "bad id");
  const holding = ctx.reserved[e.id];
  if (holding !== undefined) {
    addStock(ctx, holding.item, holding.qty);
    delete ctx.reserved[e.id];
    ctx.orders[e.id] = "expired";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return undefined;
}

/** Dispatch: pick the handler for an event type instead of an if/else ladder. */
const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

/* ------------------------------------------------------------------ *
 *  Public entry point: validate payload, then fold events through the
 *  chosen handlers into a shared context and report the result.
 * ------------------------------------------------------------------ */
export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const ctx: Ctx = { stock, orders: {}, reserved: {}, queue: [], wants: {}, rejected: 0 };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const handler = HANDLERS[event.type as string];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const error = handler(ctx, event, index);
    if (error !== undefined) {
      return { ok: false, error };
    }
  }

  return {
    ok: true,
    orders: ctx.orders,
    stock: ctx.stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

