        delete pendingWants[event.id];
        orders[event.id] = "cancelled";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "ship") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      if (reserved[event.id] === undefined) {
        rejected = rejected + 1;
      } else if (event.qty === undefined || (event.qty as number) === reserved[event.id].qty) {
        delete reserved[event.id];
        orders[event.id] = "shipped";
      } else if ((event.qty as number) < reserved[event.id].qty) {
        reserved[event.id].qty = reserved[event.id].qty - (event.qty as number);
        orders[event.id] = "partial";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "restock") {
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      stock[event.item] = (stock[event.item] ?? 0) + (event.qty as number);
      releaseQueue(stock, reserved, pendingWants, queue, orders);
    } else if (event.type === "expire") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        releaseHeld(event.id, "expired", stock, reserved, orders);
        releaseQueue(stock, reserved, pendingWants, queue, orders);
      } else {
        rejected = rejected + 1;
      }
    } else {
      return { ok: false, error: "event " + index + ": bad type" };
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

// Give a cancelled/expired reserved order's stock back to the shelf and mark it.
function releaseHeld(
  id: string,
  status: string,
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  orders: Record<string, string>,
): void {
  const holding = reserved[id];
  stock[holding.item] = (stock[holding.item] ?? 0) + holding.qty;
  delete reserved[id];
  orders[id] = status;
}

// Fulfill as many queued (backordered) wants as current stock allows.
function releaseQueue(
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  queue: string[],
  orders: Record<string, string>,
): void {
  for (let position = 0; position < queue.length; position++) {
    const pendingId = queue[position];
    const want = pendingWants[pendingId];
    if ((stock[want.item] ?? 0) >= want.qty) {
      stock[want.item] = (stock[want.item] ?? 0) - want.qty;
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pendingWants[pendingId];
      queue.splice(position, 1);
      position = position - 1;
    }
  }
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

type Ctx = {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
};

/** Stock on hand for an item, treating "not tracked" as zero. */
function held(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

/** Return an order's reservation to stock, recording its final status. */
function release(ctx: Ctx, id: string, status: "cancelled" | "expired"): void {
  const holding = ctx.reserved[id];
  ctx.stock[holding.item] = held(ctx.stock, holding.item) + holding.qty;
  delete ctx.reserved[id];
  ctx.orders[id] = status;
  backfill(ctx);
}

/** Fulfil waiting backorders as far as current stock allows. */
function backfill(ctx: Ctx): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    const onHand = held(ctx.stock, want.item);
    if (onHand < want.qty) {
      continue;
    }
    ctx.stock[want.item] = onHand - want.qty;
    ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
    ctx.orders[pendingId] = "reserved";
    delete ctx.pendingWants[pendingId];
    ctx.queue.splice(position, 1);
    position = position - 1;
  }
}

function doOrder(ctx: Ctx, event: Record<string, unknown>): string | null {
  const qty = event.qty;
  if (held(ctx.stock, event.item as string) >= (qty as number)) {
    ctx.stock[event.item as string] = held(ctx.stock, event.item as string) - (qty as number);
    ctx.reserved[event.id as string] = { item: event.item as string, qty: qty as number };
    ctx.orders[event.id as string] = "reserved";
  } else {
    ctx.queue.push(event.id as string);
    ctx.pendingWants[event.id as string] = { item: event.item as string, qty: qty as number };
    ctx.orders[event.id as string] = "backordered";
  }
  return null;
}

function doCancel(ctx: Ctx, event: Record<string, unknown>): string | null {
  const id = event.id as string;
  if (ctx.reserved[id] !== undefined) {
    release(ctx, id, "cancelled");
  } else if (ctx.orders[id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(id), 1);
    delete ctx.pendingWants[id];
    ctx.orders[id] = "cancelled";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

function doShip(ctx: Ctx, event: Record<string, unknown>): string | null {
  const id = event.id as string;
  const reservation = ctx.reserved[id];
  if (reservation === undefined) {
    ctx.rejected = ctx.rejected + 1;
  } else if (event.qty === undefined || (event.qty as number) === reservation.qty) {
    delete ctx.reserved[id];
    ctx.orders[id] = "shipped";
  } else if ((event.qty as number) < reservation.qty) {
    reservation.qty = reservation.qty - (event.qty as number);
    ctx.orders[id] = "partial";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

function doRestock(ctx: Ctx, event: Record<string, unknown>): string | null {
  ctx.stock[event.item as string] =
    held(ctx.stock, event.item as string) + (event.qty as number);
  backfill(ctx);
  return null;
}

function doExpire(ctx: Ctx, event: Record<string, unknown>): string | null {
  const id = event.id as string;
  if (ctx.reserved[id] !== undefined) {
    release(ctx, id, "expired");
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const ctx: Ctx = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  const handlers: Record<string, (ctx: Ctx, e: Record<string, unknown>) => string | null> = {
    order: doOrder,
    cancel: doCancel,
    ship: doShip,
    restock: doRestock,
    expire: doExpire,
  };

  const validations: Record<string, Array<"id" | "item" | "qty">> = {
    order: ["id", "item", "qty"],
    cancel: ["id"],
    ship: ["id", "qty"],
    restock: ["item", "qty"],
    expire: ["id"],
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    const fields = validations[event.type as string];
    if (fields === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    for (const field of fields) {
      const value = event[field];
      if (field === "id" || field === "item") {
        if (typeof value !== "string" || value.length === 0) {
          return { ok: false, error: "event " + index + ": bad " + field };
        }
      } else if (value === undefined && event.type === "ship") {
        continue; // qty is optional on a ship
      } else if (!Number.isInteger(value) || (value as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
    }
    if (event.type === "order" && ctx.orders[event.id as string] !== undefined) {
      return { ok: false, error: "event " + index + ": duplicate order" };
    }

    const error = handlers[event.type as string](ctx, event);
    if (error !== null) {
      return { ok: false, error: error };
    }
  }

  return {
    ok: true,
    orders: ctx.orders,
    stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  const bad = (index: number, why: string) => ({ ok: false as const, error: "event " + index + ": " + why });

  // Fulfill as many backorders as the current on-hand stock permits.
  function settleBackorders() {
    for (let position = 0; position < queue.length; position++) {
      const pendingId = queue[position];
      const want = pendingWants[pendingId];
      const onHand = stock[want.item] ?? 0;
      if (onHand >= want.qty) {
        stock[want.item] = onHand - want.qty;
        reserved[pendingId] = { item: want.item, qty: want.qty };
        orders[pendingId] = "reserved";
        delete pendingWants[pendingId];
        queue.splice(position, 1);
        position = position - 1;
      }
    }
  }

  // Return a held reservation to stock and mark it with the given status.
  function release(id: string, status: string) {
    const holding = reserved[id];
    stock[holding.item] = (stock[holding.item] ?? 0) + holding.qty;
    delete reserved[id];
    orders[id] = status;
    settleBackorders();
  }

  function handleOrder(event: Record<string, unknown>, index: number) {
    if (typeof event.id !== "string" || event.id.length === 0) return bad(index, "bad id");
    if (orders[event.id] !== undefined) return bad(index, "duplicate order");
    if (typeof event.item !== "string" || event.item.length === 0) return bad(index, "bad item");
    if (!Number.isInteger(event.qty) || (event.qty as number) < 1) return bad(index, "bad qty");
    if ((stock[event.item] ?? 0) >= (event.qty as number)) {
      stock[event.item] = (stock[event.item] ?? 0) - (event.qty as number);
      reserved[event.id] = { item: event.item, qty: event.qty as number };
      orders[event.id] = "reserved";
    } else {
      queue.push(event.id);
      pendingWants[event.id] = { item: event.item, qty: event.qty as number };
      orders[event.id] = "backordered";
    }
  }

  function handleCancel(event: Record<string, unknown>, index: number) {
    if (typeof event.id !== "string" || event.id.length === 0) return bad(index, "bad id");
    if (reserved[event.id] !== undefined) {
      release(event.id, "cancelled");
    } else if (orders[event.id] === "backordered") {
      queue.splice(queue.indexOf(event.id), 1);
      delete pendingWants[event.id];
      orders[event.id] = "cancelled";
    } else {
      rejected = rejected + 1;
    }
  }

  function handleShip(event: Record<string, unknown>, index: number) {
    if (typeof event.id !== "string" || event.id.length === 0) return bad(index, "bad id");
    if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
      return bad(index, "bad qty");
    }
    if (reserved[event.id] === undefined) {
      rejected = rejected + 1;
    } else if (event.qty === undefined || (event.qty as number) === reserved[event.id].qty) {
      delete reserved[event.id];
      orders[event.id] = "shipped";
    } else if ((event.qty as number) < reserved[event.id].qty) {
      reserved[event.id].qty = reserved[event.id].qty - (event.qty as number);
      orders[event.id] = "partial";
    } else {
      rejected = rejected + 1;
    }
  }

  function handleRestock(event: Record<string, unknown>, index: number) {
    if (typeof event.item !== "string" || event.item.length === 0) return bad(index, "bad item");
    if (!Number.isInteger(event.qty) || (event.qty as number) < 1) return bad(index, "bad qty");
    stock[event.item] = (stock[event.item] ?? 0) + (event.qty as number);
    settleBackorders();
  }

  function handleExpire(event: Record<string, unknown>, index: number) {
    if (typeof event.id !== "string" || event.id.length === 0) return bad(index, "bad id");
    if (reserved[event.id] !== undefined) {
      release(event.id, "expired");
    } else {
      rejected = rejected + 1;
    }
  }

  const HANDLERS: Record<string, (event: Record<string, unknown>, index: number) => { ok: false; error: string } | void> = {
    order: handleOrder,
    cancel: handleCancel,
    ship: handleShip,
    restock: handleRestock,
    expire: handleExpire,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const handler = HANDLERS[event.type as string];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const result = handler(event, index);
    if (result) return result;
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

// Mutable state threaded through each event handler.
interface Ctx {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pending: Record<string, Want>;
  queue: string[];
  rejected: number;
}

type Handler = (ctx: Ctx, event: Record<string, unknown>) => string | undefined;

export function processEvents(raw: unknown): FulfillmentResult {
  const parsed = parseInput(raw);
  if ("error" in parsed) {
    return { ok: false, error: parsed.error };
  }
  const { stock, events } = parsed;
  const ctx: Ctx = { stock, orders: {}, reserved: {}, pending: {}, queue: [], rejected: 0 };

  for (let index = 0; index < events.length; index++) {
    const event = events[index];
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const handler = handlers[event.type as string];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const problem = handler(ctx, event);
    if (problem !== undefined) {
      return { ok: false, error: "event " + index + ": " + problem };
    }
  }

  return {
    ok: true,
    orders: ctx.orders,
    stock: ctx.stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

// Dispatch on the event type instead of a growing if/else-if chain.
const handlers: Record<string, Handler> = {
  order,
  cancel,
  ship,
  restock,
  expire,
};

function order(ctx: Ctx, e: Record<string, unknown>): string | undefined {
  if (typeof e.id !== "string" || e.id.length === 0) return "bad id";
  if (ctx.orders[e.id] !== undefined) return "duplicate order";
  if (typeof e.item !== "string" || e.item.length === 0) return "bad item";
  if (!Number.isInteger(e.qty) || (e.qty as number) < 1) return "bad qty";
  const available = ctx.stock[e.item] ?? 0;
  if (available >= (e.qty as number)) {
    ctx.stock[e.item] = available - (e.qty as number);
    ctx.reserved[e.id] = { item: e.item, qty: e.qty as number };
    ctx.orders[e.id] = "reserved";
  } else {
    ctx.queue.push(e.id);
    ctx.pending[e.id] = { item: e.item, qty: e.qty as number };
    ctx.orders[e.id] = "backordered";
  }
}

function cancel(ctx: Ctx, e: Record<string, unknown>): string | undefined {
  if (typeof e.id !== "string" || e.id.length === 0) return "bad id";
  if (ctx.reserved[e.id] !== undefined) {
    release(ctx, e.id, "cancelled");
  } else if (ctx.orders[e.id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(e.id), 1);
    delete ctx.pending[e.id];
    ctx.orders[e.id] = "cancelled";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
}

function ship(ctx: Ctx, e: Record<string, unknown>): string | undefined {
  if (typeof e.id !== "string" || e.id.length === 0) return "bad id";
  if (e.qty !== undefined && (!Number.isInteger(e.qty) || (e.qty as number) < 1)) {
    return "bad qty";
  }
  const holding = ctx.reserved[e.id];
  if (holding === undefined) {
    ctx.rejected = ctx.rejected + 1;
  } else if (e.qty === undefined || e.qty === holding.qty) {
    delete ctx.reserved[e.id];
    ctx.orders[e.id] = "shipped";
  } else if ((e.qty as number) < holding.qty) {
    holding.qty = holding.qty - (e.qty as number);
    ctx.orders[e.id] = "partial";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
}

function restock(ctx: Ctx, e: Record<string, unknown>): string | undefined {
  if (typeof e.item !== "string" || e.item.length === 0) return "bad item";
  if (!Number.isInteger(e.qty) || (e.qty as number) < 1) return "bad qty";
  ctx.stock[e.item] = (ctx.stock[e.item] ?? 0) + (e.qty as number);
  fulfill(ctx);
}

function expire(ctx: Ctx, e: Record<string, unknown>): string | undefined {
  if (typeof e.id !== "string" || e.id.length === 0) return "bad id";
  if (ctx.reserved[e.id] !== undefined) {
    release(ctx, e.id, "expired");
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
}

// Return a held reservation to stock, marking it, then retry the queue.
function release(ctx: Ctx, id: string, status: string): void {
  const holding = ctx.reserved[id];
  ctx.stock[holding.item] = (ctx.stock[holding.item] ?? 0) + holding.qty;
  delete ctx.reserved[id];
  ctx.orders[id] = status;
  fulfill(ctx);
}

// Repeated by cancel/restock/expire: convert any backorder that now fits into a reservation.
function fulfill(ctx: Ctx): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const pendingId = ctx.queue[position];
    const want = ctx.pending[pendingId];
    const onHand = ctx.stock[want.item] ?? 0;
    if (onHand >= want.qty) {
      ctx.stock[want.item] = onHand - want.qty;
      ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
      ctx.orders[pendingId] = "reserved";
      delete ctx.pending[pendingId];
      ctx.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function parseInput(raw: unknown):
  | { error: string }
  | { stock: Record<string, number>; events: Record<string, unknown>[] } {
  if (typeof raw !== "object" || raw === null) {
    return { error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
