interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

/** Mutable state threaded through event handlers. */
interface Ledger {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

type Handler = (s: Ledger, event: Record<string, unknown>, index: number) => string | undefined;
type EventRecord = Record<string, unknown>;

function idError(event: EventRecord, index: number): string | undefined {
  return typeof event.id === "string" && event.id.length > 0 ? undefined : "event " + index + ": bad id";
}

function itemError(event: EventRecord, index: number): string | undefined {
  return typeof event.item === "string" && event.item.length > 0 ? undefined : "event " + index + ": bad item";
}

/** qty must be a positive integer (order, restock). */
function requiredQtyError(event: EventRecord, index: number): string | undefined {
  return Number.isInteger(event.qty) && (event.qty as number) >= 1
    ? undefined
    : "event " + index + ": bad qty";
}

/** qty is optional but, when present, must be a positive integer (ship). */
function optionalQtyError(event: EventRecord, index: number): string | undefined {
  return event.qty === undefined
    ? undefined
    : requiredQtyError(event, index);
}

/** Scan backorders in FIFO order, reserving each against any now-available stock. */
function fulfillPending(s: Ledger): void {
  for (let position = 0; position < s.queue.length; position++) {
    const pendingId = s.queue[position];
    const want = s.pendingWants[pendingId];
    const onHand = s.stock[want.item] === undefined ? 0 : s.stock[want.item];
    if (onHand >= want.qty) {
      s.stock[want.item] = onHand - want.qty;
      s.reserved[pendingId] = { item: want.item, qty: want.qty };
      s.orders[pendingId] = "reserved";
      delete s.pendingWants[pendingId];
      s.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

/** Return a reserved order's stock, then try to fill waiting backorders. */
function releaseHolding(s: Ledger, id: string, status: string): void {
  const holding = s.reserved[id];
  const back = s.stock[holding.item] === undefined ? 0 : s.stock[holding.item];
  s.stock[holding.item] = back + holding.qty;
  delete s.reserved[id];
  s.orders[id] = status;
  fulfillPending(s);
}

function handleOrder(s: Ledger, event: EventRecord, index: number): string | undefined {
  if (idError(event, index)) return idError(event, index);
  if (s.orders[event.id as string] !== undefined) return "event " + index + ": duplicate order";
  if (itemError(event, index)) return itemError(event, index);
  if (requiredQtyError(event, index)) return requiredQtyError(event, index);
  const item = event.item as string;
  const qty = event.qty as number;
  const available = s.stock[item] === undefined ? 0 : s.stock[item];
  if (available >= qty) {
    s.stock[item] = available - qty;
    s.reserved[event.id as string] = { item, qty };
    s.orders[event.id as string] = "reserved";
  } else {
    s.queue.push(event.id as string);
    s.pendingWants[event.id as string] = { item, qty };
    s.orders[event.id as string] = "backordered";
  }
}

function handleCancel(s: Ledger, event: EventRecord, index: number): string | undefined {
  if (idError(event, index)) return idError(event, index);
  const id = event.id as string;
  if (s.reserved[id] !== undefined) {
    releaseHolding(s, id, "cancelled");
  } else if (s.orders[id] === "backordered") {
    s.queue.splice(s.queue.indexOf(id), 1);
    delete s.pendingWants[id];
    s.orders[id] = "cancelled";
  } else {
    s.rejected++;
  }
}

function handleShip(s: Ledger, event: EventRecord, index: number): string | undefined {
  if (idError(event, index)) return idError(event, index);
  if (optionalQtyError(event, index)) return optionalQtyError(event, index);
  const id = event.id as string;
  const held = s.reserved[id];
  if (held === undefined) {
    s.rejected++;
  } else if (event.qty === undefined || (event.qty as number) === held.qty) {
    delete s.reserved[id];
    s.orders[id] = "shipped";
  } else if ((event.qty as number) < held.qty) {
    held.qty = held.qty - (event.qty as number);
    s.orders[id] = "partial";
  } else {
    s.rejected++;
  }
}

function handleRestock(s: Ledger, event: EventRecord, index: number): string | undefined {
  if (itemError(event, index)) return itemError(event, index);
  if (requiredQtyError(event, index)) return requiredQtyError(event, index);
  const item = event.item as string;
  const qty = event.qty as number;
  const held = s.stock[item] === undefined ? 0 : s.stock[item];
  s.stock[item] = held + qty;
  fulfillPending(s);
}

function handleExpire(s: Ledger, event: EventRecord, index: number): string | undefined {
  if (idError(event, index)) return idError(event, index);
  const id = event.id as string;
  if (s.reserved[id] !== undefined) {
    releaseHolding(s, id, "expired");
  } else {
    s.rejected++;
  }
}

const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const ledger: Ledger = { stock, orders: {}, reserved: {}, pendingWants: {}, queue: [], rejected: 0 };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const handler = HANDLERS[event.type as string];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const err = handler(ledger, event, index);
    if (err !== undefined) {
      return { ok: false, error: err };
    }
  }

  return {
    ok: true,
    orders: ledger.orders,
    stock: ledger.stock,
    queue: ledger.queue,
    rejected: ledger.rejected,
    report: buildReport(ledger.orders, ledger.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

