  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as AnyEvent;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    switch (event.type) {
      case "order": {
        if (!hasId(event) || typeof event.id !== "string") {
          return { ok: false, error: "event " + index + ": bad id" };
        }
        if (orders[event.id] !== undefined) {
          return { ok: false, error: "event " + index + ": duplicate order" };
        }
        if (!hasItem(event) || typeof event.item !== "string") {
          return { ok: false, error: "event " + index + ": bad item" };
        }
        if (!isValidQty(event.qty) || typeof event.qty !== "number") {
          return { ok: false, error: "event " + index + ": bad qty" };
        }
        const available = stockOnHand(stock, event.item);
        if (available >= event.qty) {
          stock[event.item] = available - event.qty;
          reserved[event.id] = { item: event.item, qty: event.qty };
          orders[event.id] = "reserved";
        } else {
          queue.push(event.id);
          pendingWants[event.id] = { item: event.item, qty: event.qty };
          orders[event.id] = "backordered";
        }
        break;
      }

      case "cancel": {
        if (!hasId(event) || typeof event.id !== "string") {
          return { ok: false, error: "event " + index + ": bad id" };
        }
        if (reserved[event.id] !== undefined) {
          const holding = reserved[event.id];
          stock[holding.item] = stockOnHand(stock, holding.item) + holding.qty;
          delete reserved[event.id];
          orders[event.id] = "cancelled";
          fulfillQueue(stock, queue, pendingWants, reserved, orders);
        } else if (orders[event.id] === "backordered") {
          queue.splice(queue.indexOf(event.id), 1);
          delete pendingWants[event.id];
          orders[event.id] = "cancelled";
        } else {
          rejected = rejected + 1;
        }
        break;
      }

      case "ship": {
        if (!hasId(event) || typeof event.id !== "string") {
          return { ok: false, error: "event " + index + ": bad id" };
        }
        if (event.qty !== undefined && (!isValidQty(event.qty) || typeof event.qty !== "number")) {
          return { ok: false, error: "event " + index + ": bad qty" };
        }
        const holding = reserved[event.id];
        if (holding === undefined) {
          rejected = rejected + 1;
        } else if (event.qty === undefined || event.qty === holding.qty) {
          delete reserved[event.id];
          orders[event.id] = "shipped";
        } else if (event.qty < holding.qty) {
          holding.qty = holding.qty - event.qty;
          orders[event.id] = "partial";
        } else {
          rejected = rejected + 1;
        }
        break;
      }

      case "restock": {
        if (!hasItem(event) || typeof event.item !== "string") {
          return { ok: false, error: "event " + index + ": bad item" };
        }
        if (!isValidQty(event.qty) || typeof event.qty !== "number") {
          return { ok: false, error: "event " + index + ": bad qty" };
        }
        stock[event.item] = stockOnHand(stock, event.item) + event.qty;
        fulfillQueue(stock, queue, pendingWants, reserved, orders);
        break;
      }

      case "expire": {
        if (!hasId(event) || typeof event.id !== "string") {
          return { ok: false, error: "event " + index + ": bad id" };
        }
        if (reserved[event.id] !== undefined) {
          const holding = reserved[event.id];
          stock[holding.item] = stockOnHand(stock, holding.item) + holding.qty;
          delete reserved[event.id];
          orders[event.id] = "expired";
          fulfillQueue(stock, queue, pendingWants, reserved, orders);
        } else {
          rejected = rejected + 1;
        }
        break;
      }

      default:
        return { ok: false, error: "event " + index + ": bad type" };
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

type Event = Record<string, unknown>;
type Handler = (ctx: Context, index: number, event: Event) => string | undefined;

interface Context {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

const evErr = (index: number, detail: string): string => "event " + index + ": " + detail;
const stockOf = (stock: Record<string, number>, item: string): number =>
  stock[item] === undefined ? 0 : stock[item];

// Refill backordered wants that now fit within available stock.
function fulfillQueue(ctx: Context): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    const onHand = stockOf(ctx.stock, want.item);
    if (onHand >= want.qty) {
      ctx.stock[want.item] = onHand - want.qty;
      ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
      ctx.orders[pendingId] = "reserved";
      delete ctx.pendingWants[pendingId];
      ctx.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

// Return a held order to stock (refilling the queue), or report that it wasn't held.
function releaseReserved(ctx: Context, id: string, status: string): boolean {
  const holding = ctx.reserved[id];
  if (holding === undefined) return false;
  ctx.stock[holding.item] = stockOf(ctx.stock, holding.item) + holding.qty;
  delete ctx.reserved[id];
  ctx.orders[id] = status;
  fulfillQueue(ctx);
  return true;
}

function handleOrder(ctx: Context, index: number, event: Event): string | undefined {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) return evErr(index, "bad id");
  if (ctx.orders[id] !== undefined) return evErr(index, "duplicate order");
  const item = event.item;
  if (typeof item !== "string" || item.length === 0) return evErr(index, "bad item");
  const qty = event.qty;
  if (!Number.isInteger(qty) || (qty as number) < 1) return evErr(index, "bad qty");
  const available = stockOf(ctx.stock, item);
  if (available >= (qty as number)) {
    ctx.stock[item] = available - (qty as number);
    ctx.reserved[id] = { item, qty: qty as number };
    ctx.orders[id] = "reserved";
  } else {
    ctx.queue.push(id);
    ctx.pendingWants[id] = { item, qty: qty as number };
    ctx.orders[id] = "backordered";
  }
}

function handleCancel(ctx: Context, index: number, event: Event): string | undefined {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) return evErr(index, "bad id");
  if (releaseReserved(ctx, id, "cancelled")) return;
  if (ctx.orders[id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(id), 1);
    delete ctx.pendingWants[id];
    ctx.orders[id] = "cancelled";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
}

function handleShip(ctx: Context, index: number, event: Event): string | undefined {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) return evErr(index, "bad id");
  const qty = event.qty;
  if (qty !== undefined && (!Number.isInteger(qty) || (qty as number) < 1)) {
    return evErr(index, "bad qty");
  }
  const holding = ctx.reserved[id];
  if (holding === undefined) {
    ctx.rejected = ctx.rejected + 1;
  } else if (qty === undefined || (qty as number) === holding.qty) {
    delete ctx.reserved[id];
    ctx.orders[id] = "shipped";
  } else if ((qty as number) < holding.qty) {
    holding.qty = holding.qty - (qty as number);
    ctx.orders[id] = "partial";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
}

function handleRestock(ctx: Context, index: number, event: Event): string | undefined {
  const item = event.item;
  if (typeof item !== "string" || item.length === 0) return evErr(index, "bad item");
  const qty = event.qty;
  if (!Number.isInteger(qty) || (qty as number) < 1) return evErr(index, "bad qty");
  ctx.stock[item] = stockOf(ctx.stock, item) + (qty as number);
  fulfillQueue(ctx);
}

function handleExpire(ctx: Context, index: number, event: Event): string | undefined {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) return evErr(index, "bad id");
  if (!releaseReserved(ctx, id, "expired")) {
    ctx.rejected = ctx.rejected + 1;
  }
}

const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const ctx: Context = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Event;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: evErr(index, "malformed") };
    }
    const handler = HANDLERS[event.type as string];
    if (handler === undefined) {
      return { ok: false, error: evErr(index, "bad type") };
    }
    const error = handler(ctx, index, event);
    if (error !== undefined) {
      return { ok: false, error };
    }
  }

  return {
    ok: true,
    orders: ctx.orders,
    stock: ctx.stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

type Stock = Record<string, number>;
type Orders = Record<string, string>;
type Reserved = Record<string, Want>;
type PendingWants = Record<string, Want>;

type Event = Record<string, unknown>;

/** Returns on-hand quantity for an item, treating an unknown item as 0. */
function onHand(stock: Stock, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

/**
 * Repeatedly scans the backorder queue front-to-back, fulfilling any pending
 * order that now has enough stock. Because fulfilling one order can free up
 * capacity for later ones, the scan restarts after each fulfillment.
 */
function fulfillQueue(
  stock: Stock,
  reserved: Reserved,
  pendingWants: PendingWants,
  queue: string[],
  orders: Orders,
): void {
  for (let position = 0; position < queue.length; position++) {
    const pendingId = queue[position];
    const want = pendingWants[pendingId];
    const available = onHand(stock, want.item);
    if (available >= want.qty) {
      stock[want.item] = available - want.qty;
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pendingWants[pendingId];
      queue.splice(position, 1);
      position = position - 1;
    }
  }
}

/** Returns true when `value` is a non-empty string. */
function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

/** Returns true when `value` is an integer greater than or equal to `min`. */
function isIntegerAtLeast(value: unknown, min: number): value is number {
  return Number.isInteger(value) && (value as number) >= min;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Stock = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    const count = rawStock[item];
    if (!isIntegerAtLeast(count, 0)) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = count;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Orders = {};
  const reserved: Reserved = {};
  const pendingWants: PendingWants = {};
  const queue: string[] = [];
  let rejected = 0;

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Event;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    if (event.type === "order") {
      if (!isNonEmptyString(event.id)) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (orders[event.id] !== undefined) {
        return { ok: false, error: "event " + index + ": duplicate order" };
      }
      if (!isNonEmptyString(event.item)) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!isIntegerAtLeast(event.qty, 1)) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      const available = onHand(stock, event.item);
      if (available >= event.qty) {
        stock[event.item] = available - event.qty;
        reserved[event.id] = { item: event.item, qty: event.qty };
        orders[event.id] = "reserved";
      } else {
        queue.push(event.id);
        pendingWants[event.id] = { item: event.item, qty: event.qty };
        orders[event.id] = "backordered";
      }
    } else if (event.type === "cancel") {
      if (!isNonEmptyString(event.id)) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      const holding = reserved[event.id];
      if (holding !== undefined) {
        stock[holding.item] = onHand(stock, holding.item) + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "cancelled";
        fulfillQueue(stock, reserved, pendingWants, queue, orders);
      } else if (orders[event.id] === "backordered") {
        queue.splice(queue.indexOf(event.id), 1);
        delete pendingWants[event.id];
        orders[event.id] = "cancelled";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "ship") {
      if (!isNonEmptyString(event.id)) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (event.qty !== undefined && !isIntegerAtLeast(event.qty, 1)) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      const shipQty = event.qty as number | undefined;
      const held = reserved[event.id];
      if (held === undefined) {
        rejected = rejected + 1;
      } else if (shipQty === undefined || shipQty === held.qty) {
        delete reserved[event.id];
        orders[event.id] = "shipped";
      } else if (shipQty < held.qty) {
        held.qty = held.qty - shipQty;
        orders[event.id] = "partial";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "restock") {
      if (!isNonEmptyString(event.item)) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!isIntegerAtLeast(event.qty, 1)) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      stock[event.item] = onHand(stock, event.item) + event.qty;
      fulfillQueue(stock, reserved, pendingWants, queue, orders);
    } else if (event.type === "expire") {
      if (!isNonEmptyString(event.id)) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      const holding = reserved[event.id];
      if (holding !== undefined) {
        stock[holding.item] = onHand(stock, holding.item) + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "expired";
        fulfillQueue(stock, reserved, pendingWants, queue, orders);
      } else {
        rejected = rejected + 1;
      }
    } else {
      return { ok: false, error: "event " + index + ": bad type" };
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Orders): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Orders, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

type EventType = "order" | "cancel" | "ship" | "restock" | "expire";

interface RawEvent {
  type?: unknown;
  id?: unknown;
  item?: unknown;
  qty?: unknown;
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isPositiveInt(value: unknown): value is number {
  return Number.isInteger(value) && (value as number) >= 1;
}

function stockOf(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

/**
 * Walk the backorder queue in FIFO order, fulfilling as many pending orders as
 * current stock allows. Mutates all shared state in place.
 */
function fulfillQueue(
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  queue: string[],
  orders: Record<string, string>,
): void {
  for (let position = 0; position < queue.length; position++) {
    const pendingId = queue[position];
    const want = pendingWants[pendingId];
    if (stockOf(stock, want.item) >= want.qty) {
      stock[want.item] = stockOf(stock, want.item) - want.qty;
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pendingWants[pendingId];
      queue.splice(position, 1);
      position = position - 1;
    }
  }
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (!isObject(raw)) {
    return { ok: false, error: "malformed input" };
  }

  const input = raw as Record<string, unknown>;
  if (!isObject(input.stock)) {
    return { ok: false, error: "bad stock" };
  }

  const stock: Record<string, number> = {};
  for (const item of Object.keys(input.stock as Record<string, unknown>)) {
    if (!Number.isInteger(input.stock[item]) || (input.stock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = input.stock[item] as number;
  }

  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  const events = input.events as unknown[];

  for (let index = 0; index < events.length; index++) {
    const event = events[index];
    if (!isObject(event)) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    const ev = event as unknown as RawEvent;

    switch (ev.type) {
      case "order": {
        if (!isNonEmptyString(ev.id)) return { ok: false, error: "event " + index + ": bad id" };
        if (orders[ev.id] !== undefined) return { ok: false, error: "event " + index + ": duplicate order" };
        if (!isNonEmptyString(ev.item)) return { ok: false, error: "event " + index + ": bad item" };
        if (!isPositiveInt(ev.qty)) return { ok: false, error: "event " + index + ": bad qty" };

        const available = stockOf(stock, ev.item);
        if (available >= ev.qty) {
          stock[ev.item] = available - ev.qty;
          reserved[ev.id] = { item: ev.item, qty: ev.qty };
          orders[ev.id] = "reserved";
        } else {
          queue.push(ev.id);
          pendingWants[ev.id] = { item: ev.item, qty: ev.qty };
          orders[ev.id] = "backordered";
        }
        break;
      }

      case "cancel": {
        if (!isNonEmptyString(ev.id)) return { ok: false, error: "event " + index + ": bad id" };

        if (reserved[ev.id] !== undefined) {
          const holding = reserved[ev.id];
          stock[holding.item] = stockOf(stock, holding.item) + holding.qty;
          delete reserved[ev.id];
          orders[ev.id] = "cancelled";
          fulfillQueue(stock, reserved, pendingWants, queue, orders);
        } else if (orders[ev.id] === "backordered") {
          queue.splice(queue.indexOf(ev.id), 1);
          delete pendingWants[ev.id];
          orders[ev.id] = "cancelled";
        } else {
          rejected = rejected + 1;
        }
        break;
      }

      case "ship": {
        if (!isNonEmptyString(ev.id)) return { ok: false, error: "event " + index + ": bad id" };
        if (ev.qty !== undefined && !isPositiveInt(ev.qty)) {
          return { ok: false, error: "event " + index + ": bad qty" };
        }

        if (reserved[ev.id] === undefined) {
          rejected = rejected + 1;
        } else if (ev.qty === undefined || ev.qty === reserved[ev.id].qty) {
          delete reserved[ev.id];
          orders[ev.id] = "shipped";
        } else if ((ev.qty as number) < reserved[ev.id].qty) {
          reserved[ev.id].qty = reserved[ev.id].qty - (ev.qty as number);
          orders[ev.id] = "partial";
        } else {
          rejected = rejected + 1;
        }
        break;
      }

      case "restock": {
        if (!isNonEmptyString(ev.item)) return { ok: false, error: "event " + index + ": bad item" };
        if (!isPositiveInt(ev.qty)) return { ok: false, error: "event " + index + ": bad qty" };

        stock[ev.item] = stockOf(stock, ev.item) + ev.qty;
        fulfillQueue(stock, reserved, pendingWants, queue, orders);
        break;
      }

      case "expire": {
        if (!isNonEmptyString(ev.id)) return { ok: false, error: "event " + index + ": bad id" };

        if (reserved[ev.id] !== undefined) {
          const holding = reserved[ev.id];
          stock[holding.item] = stockOf(stock, holding.item) + holding.qty;
          delete reserved[ev.id];
          orders[ev.id] = "expired";
          fulfillQueue(stock, reserved, pendingWants, queue, orders);
        } else {
          rejected = rejected + 1;
        }
        break;
      }

      default:
        return { ok: false, error: "event " + index + ": bad type" };
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  // Current on-hand quantity for an item (0 when the item is not yet stocked).
  const onHand = (item: string): number =>
    stock[item] === undefined ? 0 : stock[item];

  // Fulfil any queued (backordered) orders that now have enough stock on hand.
  // Walks from the front of the queue so earlier orders win.
  const drainQueue = (): void => {
    for (let position = 0; position < queue.length; position++) {
      const pendingId = queue[position];
      const want = pendingWants[pendingId];
      const hand = onHand(want.item);
      if (hand >= want.qty) {
        stock[want.item] = hand - want.qty;
        reserved[pendingId] = { item: want.item, qty: want.qty };
        orders[pendingId] = "reserved";
        delete pendingWants[pendingId];
        queue.splice(position, 1);
        position = position - 1;
      }
    }
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    if (event.type === "order") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (orders[event.id] !== undefined) {
        return { ok: false, error: "event " + index + ": duplicate order" };
      }
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      const available = onHand(event.item);
      if (available >= (event.qty as number)) {
        stock[event.item] = available - (event.qty as number);
        reserved[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "reserved";
      } else {
        queue.push(event.id);
        pendingWants[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "backordered";
      }
    } else if (event.type === "cancel") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        const back = onHand(holding.item);
        stock[holding.item] = back + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "cancelled";
        drainQueue();
      } else if (orders[event.id] === "backordered") {
        queue.splice(queue.indexOf(event.id), 1);
        delete pendingWants[event.id];
        orders[event.id] = "cancelled";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "ship") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      if (reserved[event.id] === undefined) {
        rejected = rejected + 1;
      } else if (event.qty === undefined || (event.qty as number) === reserved[event.id].qty) {
        delete reserved[event.id];
        orders[event.id] = "shipped";
      } else if ((event.qty as number) < reserved[event.id].qty) {
        reserved[event.id].qty = reserved[event.id].qty - (event.qty as number);
        orders[event.id] = "partial";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "restock") {
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      const held = onHand(event.item);
      stock[event.item] = held + (event.qty as number);
      drainQueue();
    } else if (event.type === "expire") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        const back = onHand(holding.item);
        stock[holding.item] = back + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "expired";
        drainQueue();
      } else {
        rejected = rejected + 1;
      }
    } else {
      return { ok: false, error: "event " + index + ": bad type" };
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

