const MAX_READINGS = 500;
const UNITS = ["uV", "mV", "V"];

// Dispatch table: unit -> converter to millivolts.
const TO_MILLIVOLTS: Record<string, (value: number) => number> = {
  V: (value) => value * 1000,
  mV: (value) => value,
  uV: (value) => Math.trunc(value / 1000),
};

// Signal thresholds (millivolts) -> label, checked high to low.
const CLASS_BANDS: Array<[number, string]> = [
  [900, "critical"],
  [600, "loaded"],
  [200, "active"],
  [50, "idle"],
  [0, "standby"],
];

const SEVERITY_RANK: Record<string, number> = {
  standby: 0,
  idle: 1,
  active: 2,
  loaded: 3,
  critical: 4,
  negative: 5,
};

const ALERT_LABELS = new Set(["negative", "loaded", "critical"]);

export function processBatch(raw: unknown): BatchResult {
  const batchError = validateBatch(raw);
  if (batchError !== null) {
    return { ok: false, error: batchError };
  }
  const entries = (raw as { readings: unknown[] }).readings;
  const parsed: ParsedReading[] = [];
  const labels: string[] = [];
  const alerts: string[] = [];
  for (let index = 0; index < entries.length; index++) {
    const outcome = parseReading(entries[index], index);
    if (typeof outcome === "string") {
      return { ok: false, error: outcome };
    }
    const millivolts = TO_MILLIVOLTS[outcome.unit](outcome.value);
    const label = classifySignal(millivolts);
    parsed.push({ channel: outcome.channel, millivolts, at: outcome.at });
    labels.push(label);
    if (ALERT_LABELS.has(label)) {
      alerts.push(outcome.channel + ":" + label);
    }
  }
  const channels = channelSummaries(parsed, labels);
  const report = buildReport(parsed.length, Object.keys(channels).length, alerts.length, labels);
  return { ok: true, readings: parsed.length, labels, channels, alerts, report };
