  }
  const unit = record.unit as string;
  if (UNITS.indexOf(unit) < 0) {
    return "reading " + index + ": bad unit";
  }
  const value = record.value as number;
  if (!Number.isInteger(value)) {
    return "reading " + index + ": bad value";
  }
  const at = record.at as number;
  if (!isNonNegativeInt(at)) {
    return "reading " + index + ": bad timestamp";
  }
  return { channel: record.channel, millivolts: normalizeValue(unit, value), at };
}

