  for (let index = 0; index < entries.length; index++) {
    const outcome = parseReading(entries[index], index);
    if (isError(outcome)) {
      return { ok: false, error: outcome };
    }

    const millivolts = normalizeValue(outcome.unit, outcome.value);
    parsed.push({ channel: outcome.channel, millivolts, at: outcome.at });

    const label = classifySignal(millivolts);
    labels.push(label);
    accumulateSummary(channels, outcome.channel, millivolts, label);

    if (severityRank(label) > severityRank(worstLabel)) {
      worstLabel = label;
    }

    const alertClass = alertForMillivolts(millivolts);
    if (alertClass !== null) {
      alerts.push(outcome.channel + ":" + alertClass);
    }
  }

